import type { Lesson } from '@/types';

export const LESSONS: Lesson[] = [
  { id: 'ancient-01', eraId: 'ancient', order: 1, title: 'The First Civilizations', subtitle: 'Mesopotamia and Egypt', estimatedMinutes: 14, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Ancient_ziggurat_at_Ali_Air_Base_Iraq_2005.jpg/1280px-Ancient_ziggurat_at_Ali_Air_Base_Iraq_2005.jpg',
    keyFacts: ['Sumer invented writing (cuneiform) around 3100 BCE', 'The Egyptian Old Kingdom built the pyramids c.2686–2181 BCE', 'Hammurabi\'s Code (c.1754 BCE) is one of history\'s earliest legal codes', 'Both civilizations depended on river systems for agriculture'],
    relatedTimeline: ['t-cuneiform','t-pyramid','t-hammurabi'],
    sections: [
      { heading: 'The Cradle of Civilization', body: 'Around 3500 BCE, the Sumerians of southern Mesopotamia—the land between the Tigris and Euphrates rivers in modern Iraq—built the world\'s first cities. Uruk, the largest, may have housed 50,000 people. To manage grain surpluses and temple accounts, Sumerian scribes invented cuneiform writing around 3100 BCE, pressing wedge-shaped marks into clay tablets.\n\nThis writing system spread across the Near East and became the dominant script for over 3,000 years. Mesopotamian city-states also developed bronze tools, the wheel, and sophisticated irrigation canals that turned desert into farmland.' },
      { heading: 'Ancient Egypt: Gift of the Nile', body: 'Egypt\'s civilization emerged along the Nile around the same time as Sumer. The annual Nile flood deposited rich silt, making Egypt one of the ancient world\'s most fertile regions. Unified under Pharaoh Narmer around 3100 BCE, Egypt developed a strong centralized state ruled by god-kings.\n\nDuring the Old Kingdom (c.2686–2181 BCE), Pharaohs commanded the construction of the great pyramids at Giza—feats of engineering that remain awe-inspiring today. Egyptian hieroglyphics, mathematics, and medicine were among the most advanced of the ancient world.' },
      { heading: 'Laws, Trade, and Legacy', body: 'The Babylonian king Hammurabi (r.1792–1750 BCE) united Mesopotamia and issued one of the world\'s earliest written legal codes. The Code of Hammurabi established punishments for crimes and regulated commerce, reflecting a society built on trade and legal order.\n\nBoth Egypt and Mesopotamia maintained extensive trade networks. Egyptian gold and grain flowed to the Levant; Mesopotamian merchants traded with the Indus Valley. These early civilizations established the blueprint for organized government, religion, agriculture, and urban life that all later societies would build upon.' },
      { heading: 'Religion and the Cosmos', body: 'Religion was inseparable from political power in both civilizations. The Sumerians worshipped a pantheon of gods who controlled natural forces—storms, floods, fertility—and built towering ziggurats as temples to honor them. Priests wielded enormous influence, administering temple lands and overseeing vast grain storehouses. The most important deity, Enlil, was seen as the king of gods whose favor determined a city\'s fate.\n\nEgyptian religion centered on the afterlife and cosmic order (Ma\'at). Pharaohs were considered living gods—manifestations of Horus in life and Osiris in death. The elaborate process of mummification and the construction of pyramid tombs aimed to preserve the pharaoh\'s body for eternal life. These religious systems gave people meaning, legitimized political authority, and drove architectural achievements of staggering ambition.' },
      { heading: 'Science, Mathematics, and Medicine', body: 'Beneath their religious worldview, Mesopotamian and Egyptian scholars made astonishing practical advances. Babylonian mathematicians developed a base-60 numerical system—the source of our 60-minute hour and 360-degree circle. They solved quadratic equations and tracked planetary movements over centuries with meticulous accuracy.\n\nEgyptian medicine was equally impressive. The Edwin Smith Papyrus (c.1600 BCE) describes surgical treatments with clinical observation, recognizing that brain injuries cause specific paralysis. Egyptian physicians understood anatomy through mummification and developed treatments for broken bones and infections. This body of practical knowledge, though mingled with magical remedies, laid groundwork for later Greek medicine and, ultimately, modern science.' },
    ] },

  { id: 'ancient-02', eraId: 'ancient', order: 2, title: 'Classical Greece', subtitle: 'Democracy, Philosophy, and War', estimatedMinutes: 16, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/d/da/The_Parthenon_in_Athens.jpg',
    keyFacts: ['Athens established the world\'s first democracy around 508 BCE', 'The Persian Wars (499–449 BCE) united the Greek city-states', 'Socrates, Plato, and Aristotle founded Western philosophy', 'Alexander the Great spread Greek culture from Egypt to India'],
    relatedTimeline: ['t-democracy','t-persian-wars','t-alexander'],
    sections: [
      { heading: 'The Greek City-States', body: 'Ancient Greece was not a unified nation but a collection of independent city-states (poleis), each with its own government and culture. Athens and Sparta were the most powerful. Sparta developed a militaristic society; every male citizen trained as a soldier from age seven. Athens, by contrast, became a center of art, philosophy, and political innovation.\n\nAround 508 BCE, the Athenian reformer Cleisthenes introduced demokratia—rule by the people—the world\'s first democratic government. Citizens (free adult males) voted directly on laws and policies in the Assembly, a revolutionary idea that would influence all future democracies.' },
      { heading: 'War and Conflict', body: 'When the Persian Empire invaded Greece in 490 BCE, the Athenians defeated them at Marathon. A second Persian invasion in 480 BCE saw the legendary Spartan stand at Thermopylae before the Athenians destroyed the Persian fleet at Salamis.\n\nVictory over Persia brought Athens to the height of its power. The Athenian leader Pericles used tribute money to build the Parthenon on the Acropolis, a masterpiece of classical architecture. But rivalry between Athens and Sparta erupted in the devastating Peloponnesian War (431–404 BCE), which exhausted both powers.' },
      { heading: 'The Philosophers', body: 'Classical Athens produced some of history\'s greatest thinkers. Socrates taught through questioning, challenging Athenians to examine their beliefs. His method—the Socratic method—remains central to education today. Socrates was sentenced to death in 399 BCE for "corrupting the youth."\n\nHis student Plato wrote dialogues exploring justice, beauty, and the ideal state. Plato\'s student Aristotle systematized logic, biology, ethics, and politics, tutoring the young Alexander of Macedon. Alexander the Great (r.336–323 BCE) conquered an empire stretching from Greece to Egypt and India, spreading Greek language and culture—Hellenism—across the ancient world.' },
      { heading: 'Art, Architecture, and the Olympic Games', body: 'Greek art and architecture reflected a pursuit of ideal beauty and proportion. The Parthenon atop Athens\' Acropolis—built between 447 and 432 BCE under the supervision of the sculptor Pheidias—exemplifies this pursuit. Its columns subtly bulge in the middle to correct optical illusions, creating the impression of perfect straightness. Greek sculptors like Myron and Praxiteles depicted the human body in idealized, naturalistic poses, far surpassing the rigid frontality of earlier art styles.\n\nThe Olympic Games, founded in 776 BCE at Olympia in honor of Zeus, brought athletes from across the Greek world every four years. During the games, wars were suspended under a sacred truce. Events included running, wrestling, discus throwing, chariot racing, and the pentathlon. Olympic victors won only an olive wreath—yet were celebrated as heroes in their home cities and immortalized in victory odes by poets like Pindar. The Games embodied the Greek ideal of arete: excellence, virtue, and competitive striving.' },
      { heading: 'The Hellenistic Age: Greece Goes Global', body: 'Alexander the Great\'s conquests spread Greek language, culture, and institutions across a vast swathe of the ancient world—from Egypt to Bactria (modern Afghanistan). This "Hellenistic" world supported magnificent cities: Alexandria in Egypt, with its legendary Library housing perhaps 500,000 scrolls; Antioch in Syria; Pergamon in Anatolia. These cosmopolitan centers blended Greek, Persian, Egyptian, and Indian traditions.\n\nHellenistic scholars made spectacular advances. Eratosthenes calculated Earth\'s circumference with remarkable accuracy using shadows and geometry. Euclid systematized geometry; Archimedes calculated pi and discovered principles of buoyancy and the lever. Aristarchus even proposed that Earth orbited the Sun—seventeen centuries before Copernicus. When Rome eventually absorbed the Hellenistic kingdoms, it preserved and transmitted this intellectual heritage, making Classical Greece the fountainhead of Western civilization.' },
    ] },

  { id: 'ancient-03', eraId: 'ancient', order: 3, title: 'The Roman Republic and Empire', subtitle: 'From Seven Hills to World Dominion', estimatedMinutes: 18, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/1/10/Colosseum_in_Rome%2C_Italy_-_April_2007.jpg',
    keyFacts: ['Rome was founded as a republic around 509 BCE', 'Julius Caesar was assassinated on 15 March 44 BCE', 'At its height, the Roman Empire covered 5 million km²', 'The Western Roman Empire fell in 476 CE'],
    relatedTimeline: ['t-roman-republic','t-caesar','t-pax-romana','t-rome-fall'],
    sections: [
      { heading: 'The Roman Republic', body: 'According to tradition, Rome was founded in 753 BCE on seven hills beside the Tiber River. After expelling its kings around 509 BCE, Rome became a republic governed by elected consuls and a Senate of aristocrats. Over time, plebeians won greater rights through the Twelve Tables—Rome\'s first written law code.\n\nRome expanded steadily across Italy, defeating rivals through military discipline and clever diplomacy. By 264 BCE, Rome controlled the Italian peninsula and set its sights on the wider Mediterranean world.' },
      { heading: 'Conquest and the Punic Wars', body: 'Rome\'s clash with Carthage produced the three Punic Wars (264–146 BCE). The Carthaginian general Hannibal famously crossed the Alps with war elephants and devastated Roman armies at Cannae in 216 BCE. Yet Rome\'s resilience prevailed; Carthage was ultimately destroyed in 146 BCE.\n\nRoman conquest brought great wealth but also social tension. Generals like Marius and Sulla commanded personal armies loyal to them rather than the Senate. Julius Caesar\'s military genius in Gaul made him the most powerful man in Rome—until his assassination on the Ides of March, 44 BCE.' },
      { heading: 'Empire and the Pax Romana', body: 'Caesar\'s heir Octavian defeated his rivals and became Rome\'s first emperor as Augustus in 27 BCE. The Augustan age inaugurated the Pax Romana—two centuries of relative stability, prosperity, and cultural achievement. The Roman road network, aqueducts, and legal system unified a vast empire from Britain to Mesopotamia.\n\nAt its height under Emperor Trajan, Rome\'s empire covered 5 million square kilometers and held perhaps 70 million people. But overexpansion, economic strain, and military pressure from Germanic tribes gradually weakened the empire. In 476 CE, the last Western Roman emperor was deposed.' },
      { heading: 'Roman Engineering and Daily Life', body: 'Roman civilization was as much a feat of engineering as of politics. The Romans built over 80,000 km of roads paved with fitted stone. They invented concrete, allowing the construction of the Pantheon\'s unreinforced dome—still the world\'s largest after 2,000 years—vast aqueducts carrying fresh water hundreds of kilometers, and the Colosseum seating 80,000 spectators.\n\nDaily Roman life was startlingly recognizable. Urban Romans lived in multi-story apartment buildings (insulae), shopped at bakeries and taverns, visited public baths (thermae) to socialize, and attended gladiatorial games and chariot races. Roman law, systematized in Emperor Justinian\'s Corpus Juris Civilis (529 CE), forms the foundation of legal systems across Europe and Latin America to this day.' },
      { heading: 'The Rise of Christianity', body: 'In the reign of Augustus, a Jewish teacher named Jesus of Nazareth was born in Roman Judaea. Crucified under the Roman governor Pontius Pilate around 30 CE, Jesus\'s followers believed he had risen from the dead. Christianity spread rapidly along Roman roads, appealing especially to slaves, women, and the poor with its message of equality and spiritual redemption. By 300 CE, perhaps 10% of the empire was Christian.\n\nIn 313 CE, Emperor Constantine issued the Edict of Milan, legalizing Christianity. By 380 CE, it was the official religion. Christianity\'s adoption transformed the empire and all of Western history—shaping education, art, philosophy, and law. As the Western Empire fell in the 5th century, the Church survived as the main institutional continuity between the ancient and medieval worlds, preserving Latin literacy and transmitting Rome\'s accumulated wisdom to future generations.' },
    ] },

  { id: 'ancient-04', eraId: 'ancient', order: 4, title: 'The Ancient East', subtitle: 'Persia, India, and China', estimatedMinutes: 15, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/9/99/Persepolis_I.jpg',
    keyFacts: ['The Achaemenid Persian Empire was the largest empire of the ancient world', 'Emperor Ashoka of India promoted Buddhist ethics across Asia', 'The Han Dynasty unified China and established the civil service exam', 'The Silk Road connected China to the Mediterranean by 100 BCE'],
    relatedTimeline: ['t-silk-road', 't-cyrus-great', 't-ashoka', 't-han-dynasty'],
    sections: [
      { heading: 'The Persian Empire', body: 'Under Cyrus the Great (r.550–530 BCE), the Achaemenid Persians built the ancient world\'s largest empire, stretching from Anatolia to the Indus Valley. Unlike many ancient conquerors, Cyrus was known for religious tolerance—he allowed the Jewish exiles in Babylon to return to their homeland.\n\nDarius I organized the empire into provinces (satrapies) and built the Royal Road stretching 2,700 km from Sardis to Susa, enabling rapid communication. Persian culture—Zoroastrian religion, monumental architecture at Persepolis, and sophisticated administration—deeply influenced all later Near Eastern civilizations.' },
      { heading: 'India: The Maurya Empire and Ashoka', body: 'India\'s Maurya Empire (322–185 BCE), founded by Chandragupta Maurya, was the first to unify most of the Indian subcontinent. His grandson Ashoka (r.268–232 BCE) became one of history\'s most remarkable rulers. After the brutal conquest of Kalinga, Ashoka converted to Buddhism and governed according to dharma (ethical duty).\n\nAshoka\'s rock edicts promoted tolerance, non-violence, and welfare. He sent Buddhist missionaries to Sri Lanka, Central Asia, and Greece, helping spread Buddhism across Asia. Indian mathematics—particularly the concept of zero and the decimal system—would later transform the world through Arab scholars.' },
      { heading: 'China and the Silk Road', body: 'China\'s Han Dynasty (206 BCE–220 CE) ruled one of the ancient world\'s most sophisticated civilizations. Emperor Wu expanded the empire into Central Asia and established the Silk Road—trade routes linking China to Rome. Silk, spices, and ideas flowed both ways along these routes.\n\nHan China developed paper, the seismograph, and cast iron. Confucian ethics shaped governance; the civil service examination system—admitting officials based on merit—was a revolutionary concept. When the Han Dynasty fell in 220 CE, China fragmented, but the Han model of unified imperial rule remained the ideal for all subsequent Chinese dynasties.' },
      { heading: 'The Vedic Age and Hindu Civilization', body: 'Around 1500 BCE, Indo-European peoples called the Aryans migrated into northern India, bringing Sanskrit and a complex polytheistic religion. The Vedas—among the world\'s oldest sacred texts—were composed in this era: hymns addressed to gods like Indra (war), Varuna (cosmic order), and Agni (fire). Over centuries, this Vedic religion evolved into Hinduism, incorporating local traditions and developing rich philosophical schools.\n\nHindu philosophy produced the Upanishads—profound metaphysical texts exploring the nature of the self (Atman) and ultimate reality (Brahman). The concepts of dharma (moral duty), karma (action and consequence), and samsara (the cycle of rebirth) provided a comprehensive framework for ethics and cosmology. The epic poems Mahabharata and Ramayana encoded Hindu values for millions across Asia and remain living cultural touchstones today.' },
      { heading: 'Chinese Philosophy: Confucius, Laozi, and Legalism', body: 'The Warring States era in China (475–221 BCE) was paradoxically one of its most intellectually creative periods. Confucius (551–479 BCE) argued that social harmony rested on proper relationships—between ruler and subject, parent and child—governed by ritual (li), benevolence (ren), and righteousness (yi). Confucianism became China\'s dominant political philosophy for over 2,000 years.\n\nLaozi offered a contrasting vision in the Tao Te Ching: the Way (Tao) was an ineffable natural order; good government meant minimal interference. Taoism profoundly shaped Chinese art, medicine, and spirituality. Legalism took the opposite view—Han Feizi argued rulers should use strict laws and harsh punishments to control society. The Qin dynasty used Legalist principles to unify China in 221 BCE under the first emperor, Qin Shi Huang, who built the Great Wall and an army of terracotta warriors to guard his spectacular tomb.' },
    ] },

  { id: 'medieval-01', eraId: 'middle-ages', order: 1, title: 'The Fall of Rome and Early Middle Ages', subtitle: 'From Empire to Feudal Europe', estimatedMinutes: 14, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/e/e5/Charlemagne_by_Albrecht_D%C3%BCrer.jpg',
    keyFacts: ['The Western Roman Empire fell in 476 CE', 'Charlemagne was crowned Holy Roman Emperor in 800 CE', 'Feudalism organized medieval society into lords and serfs', 'The Catholic Church preserved literacy and learning after Rome\'s fall'],
    relatedTimeline: ['t-rome-fall','t-charlemagne'],
    sections: [
      { heading: 'The Collapse of Rome', body: 'By the 5th century CE, the Western Roman Empire was crumbling under pressure from Germanic tribes, economic collapse, and political instability. In 410 CE, the Visigoths sacked Rome—an event that shocked the ancient world. In 476 CE, the Germanic chieftain Odoacer deposed the last Western emperor, marking the traditional end of Rome.\n\nGermanic kingdoms—Franks, Visigoths, Ostrogoths—replaced Roman provinces. The Catholic Church maintained continuity, preserving Latin literacy and providing social services across the former empire.' },
      { heading: 'Charlemagne and the Carolingian Renaissance', body: 'The Frankish king Charlemagne (r.768–814 CE) reunited much of Western Europe through conquest. On Christmas Day 800, Pope Leo III crowned him "Emperor of the Romans." Charlemagne promoted education, standardized weights and measures, and brought scholars to his court at Aachen.\n\nThe Carolingian Renaissance helped preserve classical texts. After Charlemagne\'s death, his empire was divided among his grandsons under the Treaty of Verdun (843), creating the rough outlines of modern France and Germany.' },
      { heading: 'Feudalism and Medieval Society', body: 'Medieval European society organized itself around feudalism—a hierarchical system of land ownership and military obligation. Kings granted land to nobles in exchange for military service. Nobles sublet to knights; peasants (serfs) worked the land in exchange for protection. The manor—a self-sufficient estate—was the basic economic unit.\n\nThe Catholic Church stood apart from—and often above—this secular hierarchy. Monasteries preserved manuscripts, ran schools, and provided hospitals. This interweaving of religious and secular power defined medieval European civilization.' },
      { heading: 'The Byzantine Empire: Rome\'s Eastern Heir', body: 'While Western Rome crumbled, the Eastern Roman Empire—known as the Byzantine Empire—survived for another thousand years, finally falling to the Ottoman Turks in 1453. Constantinople (modern Istanbul), built by Emperor Constantine in 330 CE on the Bosphorus, was for centuries Europe\'s largest and wealthiest city. Under Emperor Justinian I (r.527–565 CE), Byzantium reconquered much of the former Western Empire and produced the Hagia Sophia—its magnificent domed church—and the Corpus Juris Civilis, a systematic codification of Roman law.\n\nByzantium served as a crucial cultural bridge. Greek and Roman classics were preserved in Byzantine libraries when Western literacy had sharply declined. Byzantine scholars fleeing the Ottoman advance in the 15th century brought manuscripts to Italy, helping trigger the Renaissance. Byzantine art—iconic mosaics of gold and rich color—defined a tradition that spread through Eastern Europe and Russia, where Orthodox Christianity took deep root.' },
      { heading: 'The Viking Age and Norse Expansion', body: 'Between roughly 793 and 1100 CE, the Norse peoples of Scandinavia launched a dramatic expansion across Europe and beyond. Their longships—shallow-draft, ocean-worthy vessels that could navigate both open seas and rivers—gave them unparalleled mobility. The 793 raid on the monastery of Lindisfarne announced the Viking Age to a horrified Europe.\n\nBut Vikings were more than raiders. Norse traders established routes from the Baltic to Constantinople and Baghdad. Swedish-Norse (Varangian) warriors founded the Rus\' state—ancestor of Russia and Ukraine—around Novgorod and Kiev. Norwegian Vikings settled Iceland, Greenland, and around 1000 CE, Leif Eriksson reached North America—five centuries before Columbus. Norse settlers in northern France became the Normans, who conquered England in 1066 and transformed its culture, language, and governance.' },
    ] },

  { id: 'medieval-02', eraId: 'middle-ages', order: 2, title: 'The Crusades and the Islamic Golden Age', subtitle: 'Faith, Knowledge, and Conflict', estimatedMinutes: 16, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/93/Krak_des_Chevaliers_Syria_2006.jpg/1280px-Krak_des_Chevaliers_Syria_2006.jpg',
    keyFacts: ['Islam spread from Arabia across the Middle East and North Africa within 100 years of Muhammad\'s death', 'The Islamic Golden Age (8th–13th centuries) preserved and advanced Greek science', 'The First Crusade captured Jerusalem in 1099', 'The Crusades increased trade and cultural exchange between Europe and the East'],
    relatedTimeline: ['t-islam','t-golden-age','t-crusades'],
    sections: [
      { heading: 'The Rise of Islam', body: 'In 610 CE, the merchant Muhammad received his first revelation in a cave near Mecca, beginning the religion of Islam. By his death in 632 CE, most of Arabia was united under Islam. Within a century, Arab armies had conquered the Persian Empire, Egypt, North Africa, and Spain—one of history\'s most rapid imperial expansions.\n\nThe Umayyad and Abbasid caliphates created a vast, cosmopolitan Islamic world stretching from the Atlantic to Central Asia. Arabic became the language of scholarship, trade, and religion, binding together diverse peoples from Spain to Persia.' },
      { heading: 'The Islamic Golden Age', body: 'While Western Europe recovered slowly from Rome\'s fall, the Islamic world experienced a golden age of intellectual achievement (8th–13th centuries). The Abbasid court in Baghdad became the world\'s greatest center of learning. Scholars translated Greek texts by Aristotle, Euclid, and Galen, preserving them from loss.\n\nIslamic scholars made original contributions across mathematics (algebra was developed by al-Khwarizmi), astronomy, medicine (Ibn Sina\'s Canon of Medicine was used in European universities for centuries), and optics. This knowledge later flowed back to Europe, helping ignite the Scientific Revolution.' },
      { heading: 'The Crusades', body: 'In 1095, Pope Urban II called for a holy war to recapture Jerusalem from the Seljuk Turks. The First Crusade succeeded—Jerusalem fell to Crusader forces in 1099. Four Crusader states were established in the Holy Land. But Christian control proved fragile; Saladin, the Kurdish sultan of Egypt, retook Jerusalem in 1187.\n\nSeven major Crusades followed over two centuries. Though ultimately failing militarily, they profoundly shaped both European and Islamic civilizations. They intensified trade with the East, introduced Europeans to Islamic scholarship and goods, and left deep religious hatreds that echoed for centuries.' },
      { heading: 'Saladin, Chivalry, and the Later Crusades', body: 'Saladin (1137–1193), the Kurdish general who united Muslim Egypt and Syria, became one of the medieval world\'s most admired rulers—by Christians and Muslims alike. In 1187, his forces retook Jerusalem, treating Christian inhabitants with a mercy that contrasted sharply with the massacre that had accompanied the First Crusade\'s capture of the city. The Third Crusade brought Europe\'s greatest warrior-kings—Richard I of England and Philip II of France—to the Holy Land.\n\nRichard and Saladin\'s legendary duel ended in a treaty allowing Christian pilgrims access to Jerusalem. The Crusades crystallized the concept of chivalry—a code of knightly conduct combining military prowess with Christian ideals and courtly courtesy. Military orders like the Knights Templar and Hospitallers blended monastic discipline with martial expertise, embodying ideals that shaped European aristocratic culture for centuries.' },
      { heading: 'Medieval Trade and the Italian City-States', body: 'The Crusades dramatically intensified trade between Europe and the Islamic world. Italian city-states—Venice, Genoa, Pisa—provided transport for Crusaders in exchange for trading rights in Eastern ports. Venetian merchants imported spices, silk, glass, and luxury goods that enriched Italy and transformed European consumer culture.\n\nThis wealth fueled an urban commercial revolution. Northern Italian cities developed sophisticated financial instruments: letters of credit, double-entry bookkeeping, marine insurance, and early banking. The Medici family of Florence were bankers to popes and kings. This commercial sophistication created the capital and entrepreneurial culture that would fund the Renaissance—demonstrating that medieval Europe was far more dynamic than "dark ages" stereotypes suggest.' },
    ] },

  { id: 'medieval-03', eraId: 'middle-ages', order: 3, title: 'The Black Death and Late Medieval Crisis', subtitle: 'Plague, Revolt, and Cultural Change', estimatedMinutes: 14, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Danse_macabre_by_Michael_Wolgemut.png/1280px-Danse_macabre_by_Michael_Wolgemut.png',
    keyFacts: ['The Black Death killed 30–60% of Europe\'s population (1347–1353)', 'The plague originated in Central Asia and spread via trade routes', 'Labor shortages after the plague empowered surviving peasants', 'The crisis accelerated the end of feudalism and the rise of the Renaissance'],
    relatedTimeline: ['t-black-death'],
    sections: [
      { heading: 'Origins and Spread of the Plague', body: 'The Black Death—caused by the bacterium Yersinia pestis, carried by fleas on rats—originated in Central Asia around 1340. Spreading along trade routes, it reached the Black Sea ports in 1346 and entered Europe through Sicily in October 1347. Within five years, it had swept from Portugal to Poland.\n\nThe disease took three forms: bubonic plague (swollen lymph nodes), pneumonic plague (lung infection), and septicemic plague (blood infection). Contemporary medicine was powerless. Cities were hardest hit—London lost perhaps half its population; Florence lost 60%.' },
      { heading: 'Death, Chaos, and Resilience', body: 'At its peak, the Black Death killed thousands per day in major cities. Bodies piled up faster than they could be buried. Social order broke down; priests refused last rites, doctors fled. Some turned to flagellant movements—publicly whipping themselves as penance. Paranoid communities massacred Jewish populations, falsely blaming them for poisoning wells.\n\nBy the time the worst waves passed in the 1350s, Europe had lost between one-third and one-half of its population. The psychological trauma was immense. Art and literature became saturated with death imagery; the "dance of death" (danse macabre) became a popular motif reflecting a society profoundly shaken by mortality\'s randomness.' },
      { heading: 'Social and Cultural Consequences', body: 'The plague\'s aftermath transformed European society. With so many peasants dead, survivors could demand higher wages and better conditions. Serfdom declined rapidly in Western Europe. The English Peasants\' Revolt of 1381 showed the lower classes were no longer willing to accept their traditional station.\n\nThe Church, which had failed to explain or stop the catastrophe, lost prestige. Questioning of Church authority helped lay the groundwork for the Renaissance and later the Protestant Reformation. Perversely, the labor shortage accelerated technological innovation—labor-saving devices became more economically valuable, including the printing press.' },
      { heading: 'The Hundred Years\' War (1337–1453)', body: 'Concurrent with the Black Death, England and France fought the Hundred Years\' War—a series of conflicts over English claims to the French throne lasting 116 years. English longbowmen devastated French cavalry at Crécy (1346) and Agincourt (1415), where Henry V\'s outnumbered forces routed an army five times their size. English forces penetrated deep into France and at their peak controlled much of the country.\n\nThe war\'s turning point came through Joan of Arc, a teenage peasant girl from Domrémy who claimed divine visions commanding her to lead France\'s army. French forces reversed the tide; Joan was captured by the English and burned at the stake in 1431—but her campaigns had broken English dominance. By 1453, England had lost all French territory except Calais. The war demonstrated that the era of heavily armored knights was giving way to infantry and artillery.' },
      { heading: 'Seeds of the Renaissance', body: 'Paradoxically, the crises of the 14th century—plague, war, papal schism—helped produce the conditions for Renaissance cultural renewal. The Black Death created enormous wealth transfers as survivors inherited the property of the dead; this concentration of capital funded patronage of arts and learning. The Church\'s loss of prestige encouraged independent thinking.\n\nEarly humanists like Petrarch (1304–1374)—often called the "first Renaissance man"—collected classical manuscripts and placed human dignity at the center of his worldview. Boccaccio\'s Decameron depicted the Black Death while celebrating wit and human resilience. In art, Giotto broke from Byzantine flatness to depict three-dimensional, emotionally expressive figures—a revolution that opened the door to Renaissance naturalism. Late medieval culture, far from being simply dark, was pregnant with the transformations to come.' },
    ] },

  { id: 'earlymod-01', eraId: 'early-modern', order: 1, title: 'The Renaissance and Age of Exploration', subtitle: 'Rebirth of Ideas, Discovery of Worlds', estimatedMinutes: 16, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg/1280px-Michelangelo_-_Creation_of_Adam_%28cropped%29.jpg',
    keyFacts: ['The Renaissance began in Italian city-states in the 14th century', 'Humanism placed mankind, not God, at the center of intellectual inquiry', 'Columbus reached the Americas in 1492', 'The Columbian Exchange transformed both hemispheres'],
    relatedTimeline: ['t-printing-press','t-columbus','t-vasco'],
    sections: [
      { heading: 'The Italian Renaissance', body: 'The Renaissance ("rebirth") began in the wealthy city-states of northern Italy—Florence, Venice, Milan—in the 14th century. Wealthy patrons like the Medici family of Florence funded artists, architects, and scholars, triggering an explosion of creativity. Artists studied classical Greek and Roman works to understand perspective, proportion, and the human form.\n\nLeonardo da Vinci (1452–1519) embodied the "Renaissance man"—painter, sculptor, scientist, engineer, and anatomist. Michelangelo\'s Sistine Chapel ceiling and his statue of David remain pinnacles of Western art. Architects like Brunelleschi designed the Florence Cathedral dome using rediscovered Roman techniques.' },
      { heading: 'Humanism and the Printing Press', body: 'Renaissance humanism placed human experience and reason at the center of intellectual life—a shift from the medieval focus on God and theology. Scholars studied classical texts in their original Greek and Latin, recovering lost knowledge and questioning Church interpretations.\n\nJohannes Gutenberg\'s invention of the movable-type printing press around 1440 was transformative. Books that had taken monks months to copy could now be printed in days. By 1500, over 20 million books circulated in Europe, spreading new ideas with unprecedented speed—and making the Reformation possible.' },
      { heading: 'The Age of Exploration', body: 'Portuguese sailors, seeking a sea route to Asia\'s spice trade, crept down the African coast through the 15th century. Vasco da Gama reached India in 1498. Meanwhile, Christopher Columbus, sailing for Spain, reached the Caribbean in 1492—believing he had found Asia.\n\nThe Columbian Exchange that followed transformed both hemispheres. Europeans brought horses, cattle, wheat, and devastating diseases (smallpox, measles) to the Americas; they returned with potatoes, tomatoes, maize, and tobacco. Indigenous American populations, lacking immunity to European diseases, collapsed by up to 90% within a century—one of history\'s greatest demographic catastrophes.' },
      { heading: 'The Conquistadors and the Americas', body: 'Following Columbus\'s landfall, Spain moved rapidly to exploit the Americas. Hernán Cortés, with a force of 600 Spaniards and Indigenous allies resentful of Aztec domination, overthrew the Aztec Empire (1519–1521)—an empire of millions centered on the magnificent island city of Tenochtitlan. Francisco Pizarro similarly conquered the Inca Empire of South America (1532–1533), capturing the emperor Atahualpa and executing him despite a room-sized ransom of gold and silver.\n\nThe conquest\'s consequences were devastating. European diseases killed 50–90% of native populations in some regions. Sugar cultivation created the Atlantic slave trade, kidnapping millions of Africans to work in American plantations. Spanish colonial rule, enforced through the encomienda system of forced labor, imposed a violent new social order on the surviving populations—transforming the Americas and creating a connected global economy for the first time.' },
      { heading: 'The Northern Renaissance', body: 'Renaissance ideas spread northward across the Alps in the late 15th century. Erasmus of Rotterdam (1466–1536), the greatest humanist scholar of the Northern Renaissance, used classical learning to critique Church corruption with wit and erudition. Thomas More\'s Utopia (1516) imagined an ideal society based on rational principles.\n\nIn the arts, German painter Albrecht Dürer brought Italian techniques of perspective north, creating stunning woodcuts and engravings. Flemish painters like Jan van Eyck depicted everyday life with unprecedented realism. Later, William Shakespeare (1564–1616) brought Renaissance literary humanism to the English stage, exploring human psychology with depth that has never been surpassed. The printing press was crucial to this northern spread—making humanist texts, vernacular literature, and Reformation pamphlets available to literate audiences across Europe.' },
    ] },

  { id: 'earlymod-02', eraId: 'early-modern', order: 2, title: 'The Protestant Reformation', subtitle: 'Religious Revolution and Wars of Faith', estimatedMinutes: 15, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Martin_Luther_by_Lucas_Cranach_the_Elder.jpg/800px-Martin_Luther_by_Lucas_Cranach_the_Elder.jpg',
    keyFacts: ['Martin Luther posted his 95 Theses in 1517', 'The Reformation split Western Christianity into Catholic and Protestant branches', 'The Thirty Years\' War (1618–1648) killed 8 million people', 'The Peace of Westphalia established the principle of national sovereignty'],
    relatedTimeline: ['t-luther','t-thirty-years-war','t-westphalia'],
    sections: [
      { heading: 'Crisis in the Church', body: 'By 1500, the Catholic Church faced widespread criticism for corruption, worldliness, and the selling of "indulgences"—certificates supposedly reducing time in purgatory. The papal court in Rome lived in enormous luxury, funded by taxes on ordinary Christians. Many clergy were ignorant, absentee, or openly immoral. Yet the Church tolerated no dissent; earlier reformers like Jan Hus had been burned as heretics.' },
      { heading: 'Luther and the Reformation', body: 'On October 31, 1517, the German monk Martin Luther nailed his 95 Theses to the door of Wittenberg\'s Castle Church—a list of arguments against indulgences and Church corruption. Printed and circulated across Germany within weeks, Luther\'s challenge ignited a firestorm. Summoned before the Diet of Worms in 1521, Luther refused to recant: "Here I stand; I can do no other."\n\nExcommunicated by the Pope, Luther launched the Protestant Reformation, arguing that salvation came through faith alone (sola fide), not Church rituals. Other reformers followed—Zwingli in Zurich, Calvin in Geneva. By 1560, Northern Europe was predominantly Protestant, shattering Western Christianity\'s thousand-year unity.' },
      { heading: 'Wars of Religion and the Peace of Westphalia', body: 'The Reformation triggered generations of religious war. The Thirty Years\' War (1618–1648), which began as a religious conflict in the Holy Roman Empire, became a general European war that killed 8 million people and depopulated parts of Germany by a third. Armies devastated the countryside; famine and plague followed.\n\nThe Peace of Westphalia (1648) ended the war and established new principles: rulers could determine the religion of their territories, and states should not interfere in each other\'s internal affairs. These principles of sovereignty and non-interference became the foundation of the modern international state system.' },
      { heading: 'England\'s Reformation: Henry VIII and Elizabeth I', body: 'England\'s Reformation took a political rather than theological path. Henry VIII (r.1509–1547), desperate for a male heir and blocked by the Pope from annulling his marriage to Catherine of Aragon, broke with Rome in 1534 and declared himself Supreme Head of the Church of England. He dissolved the monasteries—seizing their vast wealth—and redistributed monastic lands to the English gentry, permanently reshaping the English landscape.\n\nThe religious settlement remained volatile for decades. Henry\'s children alternated between Protestantism (Edward VI), radical Catholic reaction (Mary I, who burned nearly 300 Protestants as heretics), and the moderate Protestant Anglican settlement of Elizabeth I (r.1558–1603). Elizabeth\'s long reign stabilized England and produced a golden age of exploration, trade, and culture—Shakespeare\'s theater, Drake\'s circumnavigation of the globe, and the founding of the first English colonies in America.' },
      { heading: 'The Catholic Counter-Reformation', body: 'Rather than quietly accepting Protestant gains, the Catholic Church launched a sweeping internal reform movement. The Council of Trent (1545–1563) clarified Catholic doctrine, reformed clerical education, ended the most scandalous abuses, and established seminaries to train educated priests. Baroque art—emotionally intense, dramatically lit, visually overwhelming—was deployed as propaganda for the faith.\n\nThe Society of Jesus (Jesuits), founded by Ignatius of Loyola in 1540, became the Counter-Reformation\'s shock troops. Highly educated and disciplined, Jesuits founded universities, ran missions in Asia and the Americas, and argued Catholic theology against Protestant scholars. Francis Xavier brought Christianity to India and Japan; Matteo Ricci reached the Chinese imperial court. By 1600, the Counter-Reformation had saved southern Germany, Poland, and much of France for Catholicism—the religious map of Europe that emerged from this struggle remains largely recognizable today.' },
    ] },

  { id: 'earlymod-03', eraId: 'early-modern', order: 3, title: 'Scientific Revolution and Enlightenment', subtitle: 'Reason Reshapes the World', estimatedMinutes: 17, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/GodfreyKneller-IsaacNewton-1689.jpg/800px-GodfreyKneller-IsaacNewton-1689.jpg',
    keyFacts: ['Copernicus proposed heliocentrism in 1543', 'Newton\'s Principia (1687) established classical mechanics', 'Enlightenment thinkers challenged monarchies and the Church', 'The American and French Revolutions applied Enlightenment ideals'],
    relatedTimeline: ['t-copernicus','t-galileo','t-newton','t-american-revolution','t-french-revolution'],
    sections: [
      { heading: 'Overturning the Cosmos', body: 'For over a thousand years, Europeans believed the Earth stood motionless at the center of the universe. In 1543, the Polish astronomer Nicolaus Copernicus published On the Revolutions of the Celestial Spheres, arguing the Earth revolved around the Sun.\n\nGalileo Galilei used the telescope in 1609 to observe mountains on the Moon and moons around Jupiter—supporting the Copernican model. The Church condemned Galileo in 1633, forcing him to recant. But the evidence was overwhelming, and the old cosmology could not survive.' },
      { heading: 'Newton and the New Science', body: 'Isaac Newton (1642–1727) synthesized a century of astronomical discoveries into a unified mathematical framework. His Principia Mathematica (1687) described the laws of motion and universal gravitation—the same force that caused an apple to fall kept the Moon in orbit. Newton showed that nature operated according to mathematical laws that human reason could discover.\n\nThe "Scientific Revolution" transformed how Europeans understood knowledge itself. Francis Bacon championed empiricism—knowledge gained through observation and experiment. René Descartes contributed analytical geometry and the principle of systematic doubt. Science became a method, not just a set of facts, and that method began reshaping every field.' },
      { heading: 'The Enlightenment', body: 'The Scientific Revolution\'s success inspired intellectuals to apply reason to society, government, and religion. French philosophes—Voltaire, Montesquieu, Rousseau, Diderot—questioned traditional authority, religious dogma, and absolute monarchy. Montesquieu\'s The Spirit of the Laws argued for separation of powers; Rousseau\'s Social Contract posited that government legitimacy rested on popular consent.\n\nThese ideas traveled across the Atlantic. American founders like Jefferson drew directly on Enlightenment thought when writing the Declaration of Independence (1776). In France, Enlightenment ideas fueled revolutionary anger. When the French Revolution exploded in 1789, it swept away the monarchy, the aristocracy, and the Church\'s special privileges—remaking French society on Enlightenment principles.' },
      { heading: 'The American Revolution: Enlightenment in Practice', body: 'The American Revolution (1775–1783) was the Enlightenment\'s most dramatic real-world experiment. The thirteen British colonies in North America had developed traditions of self-government that made them receptive to Enlightenment ideas about natural rights. Thomas Jefferson\'s Declaration of Independence (1776) drew directly on John Locke\'s theory that governments derive their just powers from the consent of the governed.\n\nThe new American republic established by the Constitution (1787) implemented Montesquieu\'s separation of powers and created a federal structure balancing central and state authority. The Bill of Rights (1791) guaranteed individual liberties against government overreach. America became a laboratory for Enlightenment political theory—and its example powerfully inspired democratic movements worldwide for the next two centuries.' },
      { heading: 'The Enlightenment\'s Legacy and Limits', body: 'The Enlightenment transformed Western civilization\'s self-understanding, establishing reason, individual rights, religious tolerance, and scientific inquiry as foundational values. The American and French Revolutions institutionalized Enlightenment principles in law and government. The 19th century saw these ideas spread—nationalism, liberalism, and constitutional government reshaped Europe.\n\nYet the Enlightenment had troubling limits. Many philosophes who championed universal rights simultaneously excluded women, enslaved peoples, and non-Europeans from their theories. Voltaire wrote anti-Semitic passages; Jefferson owned slaves. The rationalist confidence that human reason alone could remake society contributed to the Terror of the French Revolution. Romantic thinkers—emphasizing emotion, nature, tradition, and the limits of reason—pushed back against cold rationalism. This tension between Enlightenment rationalism and Romantic counter-currents continues to shape Western culture today.' },
    ] },

  { id: 'modern-01', eraId: 'modern', order: 1, title: 'The Industrial Revolution', subtitle: 'Steam, Steel, and Social Change', estimatedMinutes: 16, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3b/George_Stephenson_by_Henry_William_Pickersgill_rigthcrop.jpg/800px-George_Stephenson_by_Henry_William_Pickersgill_rigthcrop.jpg',
    keyFacts: ['The Industrial Revolution began in Britain around 1760', 'Steam power transformed manufacturing, transport, and agriculture', 'Urbanization created new social classes—the factory owner and the industrial worker', 'By 1900, industrial nations dominated the globe'],
    relatedTimeline: ['t-steam-engine','t-railways','t-communist-manifesto'],
    sections: [
      { heading: 'The British Origins', body: 'The Industrial Revolution began in Britain around 1760, driven by a unique combination of factors: abundant coal and iron, a stable government, secure property rights, a growing empire providing markets and raw materials, and a culture that valued practical invention. James Watt\'s improved steam engine (1769) became its symbol—a machine that could turn heat into mechanical work.\n\nTextile mills in Lancashire, iron foundries in Birmingham, and coal mines in Wales transformed Britain\'s economy. By 1800, Britain produced more iron and steel than the rest of the world combined. Child labor was common; workers toiled 14-hour days in dangerous conditions for meager wages.' },
      { heading: 'Railroads and the Shrinking World', body: 'The steam locomotive revolutionized transportation. George Stephenson\'s Rocket (1829) inaugurated the railway age. By 1850, Britain had 10,000 km of railways; by 1900, the world had 790,000 km. Railways moved goods and people at unprecedented speed—cutting travel times from days to hours.\n\nThe telegraph, patented in the 1830s and 1840s, enabled near-instant long-distance communication. For the first time in human history, information could travel faster than a human being. These technologies created the first truly integrated national—and eventually global—markets.' },
      { heading: 'Social Consequences', body: 'Industrialization uprooted millions. Peasants migrated to industrial cities; by 1851, Britain was the world\'s first majority-urban nation. These cities were often overcrowded, polluted, and disease-ridden. Yet industrialization also created wealth, lowered prices, and eventually raised living standards.\n\nNew social classes emerged: the industrial bourgeoisie (factory owners) and the proletariat (wage laborers). Karl Marx and Friedrich Engels, observing Manchester\'s squalor, wrote The Communist Manifesto (1848), arguing class struggle was history\'s engine. Trade unions organized; workers eventually won shorter hours, better pay, and political rights.' },
      { heading: 'The Second Industrial Revolution: Steel, Electricity, and Chemistry', body: 'After 1870, a Second Industrial Revolution transformed the world\'s advanced economies—this time led by Germany and the United States alongside Britain. Steel, produced cheaply using the Bessemer converter, replaced iron; electrical power enabled factories to operate efficiently; the internal combustion engine and petroleum launched a new energy paradigm. New industries—chemicals, pharmaceuticals, electrical engineering, automobiles—depended on systematic scientific research.\n\nGermany led in chemistry and electrical engineering; American companies like Carnegie Steel and Standard Oil achieved previously inconceivable scales of production. Henry Ford\'s moving assembly line (1913) made the automobile affordable. These changes concentrated economic power in giant corporations and sharpened conflicts between industrial capital and labor—providing the context for the rise of labor unions, socialist parties, and communist revolutionary movements.' },
      { heading: 'Empire, Nationalism, and the Seeds of World War', body: 'Industrial wealth fueled European imperial expansion. By 1914, European powers controlled 85% of the world\'s land. The "Scramble for Africa" (1880s–1914) divided the continent among European powers in negotiations that had no regard for African peoples or existing political structures—creating artificial borders that provoked conflict to the present day.\n\nIndustrialization also intensified European nationalism. Germany, unified only in 1871, rapidly became the continent\'s dominant economic and military power, threatening the existing balance. An arms race between Britain and Germany produced the world\'s largest naval forces; alliance systems locked European powers into rigid obligations. By 1914, a generation of industrially-organized militaries were primed for a war that everyone assumed would be short—and turned out to be catastrophic.' },
    ] },

  { id: 'modern-02', eraId: 'modern', order: 2, title: 'The World Wars', subtitle: 'The Century of Total War', estimatedMinutes: 20, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Cheshire_Regiment_trench_Somme_1916.jpg/1280px-Cheshire_Regiment_trench_Somme_1916.jpg',
    keyFacts: ['WWI (1914–1918) killed 20 million people and destroyed four empires', 'The Treaty of Versailles (1919) imposed harsh terms on Germany', 'WWII (1939–1945) was history\'s deadliest conflict, with 70–85 million dead', 'The Holocaust murdered 6 million Jews and millions of others'],
    relatedTimeline: ['t-wwi','t-versailles','t-wwii','t-holocaust','t-hiroshima'],
    sections: [
      { heading: 'The Great War', body: 'World War I began in August 1914, triggered by the assassination of Austro-Hungarian Archduke Franz Ferdinand in Sarajevo. The underlying causes were deeper: rigid alliance systems, imperial rivalry, an arms race, and aggressive nationalism. Within weeks, the great powers of Europe were at war.\n\nThe Western Front quickly became a nightmare of trench warfare. Millions of soldiers faced each other across no-man\'s land, separated by barbed wire and machine guns. The Battle of the Somme (1916) alone produced over 1 million casualties. New weapons—poison gas, tanks, airplanes—made the war uniquely terrible. By 1918, 20 million were dead, and four great empires—Ottoman, Austro-Hungarian, Russian, and German—had collapsed.' },
      { heading: 'The Road to World War II', body: 'The Treaty of Versailles (1919) humiliated Germany with war guilt, reparations, and territorial losses. The Great Depression (1929–1939) devastated economies worldwide, creating fertile ground for extremism. Adolf Hitler\'s Nazi Party rose to power in Germany in 1933 on promises of national revival, blaming Jews and communists for Germany\'s woes.\n\nHitler remilitarized the Rhineland, annexed Austria, and seized Czechoslovakia while Britain and France, traumatized by WWI, pursued appeasement. When Germany invaded Poland on September 1, 1939, Britain and France finally declared war. WWII had begun.' },
      { heading: 'World War II and the Holocaust', body: 'WWII was the most destructive conflict in human history. Germany conquered most of Europe by 1941; Japan seized vast swaths of Asia and the Pacific. Germany\'s invasion of the Soviet Union in June 1941 opened the largest land campaign in history. America entered the war after Japan\'s attack on Pearl Harbor in December 1941.\n\nThe Nazi regime systematically murdered 6 million Jews, along with Roma, disabled people, homosexuals, and political opponents—the Holocaust. Allied forces liberated the death camps in 1945. Germany surrendered in May 1945; Japan surrendered in August after the United States dropped atomic bombs on Hiroshima and Nagasaki. Between 70 and 85 million people had died—the bloodiest conflict in human history.' },
      { heading: 'The Interwar Crisis: Depression and Totalitarianism', body: 'The 1920s began promisingly with relative economic recovery and cultural vitality (the "Roaring Twenties," jazz, modernist art). But structural weaknesses—war debts, reparations, speculative finance—made the global economy fragile. When the American stock market crashed in October 1929 and credit froze, the shock cascaded into the Great Depression. By 1932, unemployment reached 25% in America, nearly 30% in Germany.\n\nThe Depression destroyed confidence in liberal democracy and capitalism. In Italy, Mussolini\'s Fascist movement had already seized power in 1922, promising national glory and order. Hitler\'s Nazi Party exploited German unemployment and anti-Semitism to win power in 1933. Stalin\'s Soviet Union imposed forced collectivization and industrialization through terror, killing millions. The democratic powers—traumatized by WWI, divided, and appeasing—failed to confront fascism\'s expansion until it was dangerously late.' },
      { heading: 'The Post-War Order: UN, NATO, and the Atomic Age', body: 'The catastrophic scale of WWII convinced Allied leaders that a new international architecture was essential. The United Nations, established in 1945, created forums for peaceful conflict resolution. The Universal Declaration of Human Rights (1948) set international norms. The Nuremberg Trials (1945–46) established the precedent of international criminal accountability for war crimes and crimes against humanity.\n\nThe atomic bombs that ended the Pacific war inaugurated a fundamental shift in the nature of conflict—humanity now possessed weapons capable of destroying civilization. The Marshall Plan poured $13 billion into rebuilding Western Europe, creating strong democracies allied with America. NATO established a military alliance against Soviet expansion. These arrangements proved remarkably durable: the post-WWII international order, though challenged, remained the framework of global affairs into the 21st century.' },
    ] },

  { id: 'modern-03', eraId: 'modern', order: 3, title: 'The Cold War and Decolonization', subtitle: 'Two Superpowers, One Divided World', estimatedMinutes: 18, xpReward: 100, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Berlinermauer.jpg/1280px-Berlinermauer.jpg',
    keyFacts: ['The Cold War (1947–1991) was an ideological struggle between the USA and USSR', 'Both sides developed nuclear weapons capable of destroying civilization', 'Dozens of African and Asian nations gained independence in the 1950s–70s', 'The Soviet Union collapsed in 1991'],
    relatedTimeline: ['t-cold-war','t-decolonization','t-moon','t-berlin-wall'],
    sections: [
      { heading: 'The Cold War Begins', body: 'As WWII ended, the alliance between the democratic West (led by the USA) and communist East (led by the USSR) fractured. By 1947, Winston Churchill described an "Iron Curtain" dividing Europe. The USA responded with the Truman Doctrine and the Marshall Plan—billions of dollars to rebuild Western Europe and contain communism.\n\nThe Soviet Union developed its own atomic bomb in 1949; China became communist the same year. Both superpowers built vast nuclear arsenals capable of destroying civilization. The Cuban Missile Crisis of 1962—when Soviet missiles were discovered in Cuba—brought the world within hours of nuclear war before a tense diplomatic resolution.' },
      { heading: 'Proxy Wars and Competition', body: 'The Cold War was fought indirectly through proxy wars and competition for influence in the developing world. The Korean War (1950–53) ended in stalemate at roughly the 38th parallel. The Vietnam War drew massive American involvement; the US eventually withdrew after losing 58,000 soldiers, and Vietnam was reunified under communist rule.\n\nBoth superpowers competed in space—the "Space Race." The USSR launched Sputnik in 1957 and put Yuri Gagarin in orbit in 1961; the USA responded by landing on the Moon in 1969. Scientific and technological competition drove unprecedented advances.' },
      { heading: 'Decolonization and the Soviet Collapse', body: 'While the superpowers competed, the European empires collapsed. India gained independence in 1947; dozens of African nations gained independence in the 1950s and 1960s. The process was often violent—France fought brutal wars in Vietnam and Algeria. Cold War competition complicated decolonization, as each superpower backed favored factions in newly independent nations.\n\nBy the 1980s, the Soviet economy was stagnating. Mikhail Gorbachev\'s reforms (glasnost and perestroika) unleashed forces he could not control. Eastern European nations broke free in 1989—the Berlin Wall fell on November 9. In 1991, the Soviet Union itself dissolved into 15 independent states. The Cold War was over.' },
      { heading: 'The Cuban Missile Crisis: Thirteen Days at the Brink', body: 'In October 1962, the world came closer to nuclear war than at any other time in history. Soviet leader Khrushchev had secretly placed nuclear missiles in Cuba—90 miles from Florida—capable of striking most American cities. When American U-2 spy planes photographed the missile sites, President Kennedy faced an agonizing choice between air strikes, naval blockade, or capitulation.\n\nKennedy chose a naval "quarantine" and confronted Khrushchev publicly on October 22. For thirteen days, Soviet ships steamed toward the American blockade while both sides\' nuclear forces stood at highest alert. Diplomatic back-channels eventually produced a resolution: the Soviets withdrew their missiles in exchange for an American pledge not to invade Cuba and a secret agreement to remove American Jupiter missiles from Turkey. The crisis sobered both leaders profoundly; a direct telephone "hotline" between the White House and Kremlin was established within months.' },
      { heading: 'Détente, Collapse, and the New World Order', body: 'After the Cuban crisis, both superpowers sought to manage their competition more carefully. Détente—the relaxation of tensions through negotiation—characterized the late 1960s and 1970s. The Strategic Arms Limitation Treaties (SALT I, 1972) capped nuclear warhead numbers. Nixon\'s historic visit to China in 1972 reopened US relations with Beijing and complicated Soviet strategic calculations.\n\nBut détente faltered when the Soviet Union invaded Afghanistan in 1979. Reagan\'s confrontational approach in the 1980s accelerated the Soviet economic crisis. Gorbachev\'s perestroika and glasnost unleashed demands for freedom the system could not accommodate. Poland\'s Solidarity movement, Hungary\'s border opening, East Germany\'s mass exodus—all culminated in the fall of the Berlin Wall. By December 1991, the Soviet Union had dissolved. The Cold War\'s end seemed to herald a new world order of democratic peace—a hope that the subsequent decades of regional wars and great-power rivalry would complicate.' },
    ] },

  { id: 'modern-04', eraId: 'modern', order: 4, title: 'Globalization and the Contemporary World', subtitle: 'One Planet, Many Challenges', estimatedMinutes: 14, xpReward: 100, imageUrl: 'https://images.unsplash.com/photo-1477959858617-67f85cf4f1df?auto=format&fit=crop&w=1200&q=70',
    keyFacts: ['The World Wide Web was invented by Tim Berners-Lee in 1989', 'Global trade as a share of GDP doubled between 1960 and 2000', 'September 11, 2001 transformed global politics and security', 'Climate change is the defining environmental challenge of the 21st century'],
    relatedTimeline: ['t-internet','t-9-11'],
    sections: [
      { heading: 'The Digital Revolution', body: 'The invention of the personal computer (1970s), the World Wide Web (1989), and the smartphone (2007) transformed human society as profoundly as the printing press or the steam engine. By 2023, over 5 billion people had internet access. Information, culture, and commerce now flow globally in real time.\n\nSocial media platforms gave individuals unprecedented ability to communicate and organize, fueling political movements from the Arab Spring to global climate strikes. But the digital revolution also enabled misinformation, mass surveillance, and the concentration of power in a handful of technology corporations.' },
      { heading: 'Economic Globalization', body: 'The fall of the Soviet Union and China\'s opening to markets triggered the greatest economic globalization in history. Trade barriers fell; supply chains stretched across continents. Hundreds of millions escaped poverty—especially in China and India. The World Trade Organization (1995) created rules for global commerce.\n\nBut globalization\'s benefits were unevenly distributed. Manufacturing jobs moved from wealthy nations to lower-wage countries. Inequality rose within many nations even as it fell between them. The 2008 financial crisis—originating in American mortgage markets—cascaded into a global recession, demonstrating how interconnected and fragile the world economy had become.' },
      { heading: 'The 21st Century', body: 'The September 11, 2001 attacks by al-Qaeda killed 3,000 people and triggered two decades of American military involvement in Afghanistan and Iraq. Terrorism became a defining security concern of the early 21st century.\n\nClimate change—driven by the greenhouse gas emissions of industrial civilization—is the defining challenge of our era. Global temperatures are rising, sea levels are climbing, and extreme weather events are intensifying. The scientific consensus is unequivocal, yet political action has been halting. How humanity responds to climate change will shape the history of the coming centuries more than any other decision.' },
      { heading: 'The Rise of China and the Multipolar World', body: 'Perhaps no development has done more to reshape the 21st-century world than China\'s economic rise. Following Deng Xiaoping\'s market reforms beginning in 1978, China grew at nearly 10% annually for three decades—the fastest sustained growth in human history. Hundreds of millions were lifted from poverty. By the early 2020s, China\'s economy rivaled American GDP. Chinese investment reached across Africa, Asia, and Latin America through the "Belt and Road Initiative."\n\nChina\'s rise challenged the post-Cold War assumption that globalization would automatically produce democratization. The Chinese Communist Party maintained tight political control even while liberalizing the economy—demonstrating an alternative model to the liberal democratic consensus. Tensions with the United States over trade, technology, Taiwan, and the South China Sea intensified through the 2010s and 2020s. India\'s emergence, Russia\'s reassertion of great-power ambitions, and the weakening of international institutions suggested the 21st century would be more multipolar and contested than the post-Cold War moment had promised.' },
      { heading: 'The AI Revolution and Humanity\'s Next Challenges', body: 'The 2020s brought multiple converging crises that tested the international order. The COVID-19 pandemic (2020–2022) killed over 7 million people and disrupted economies worldwide, exposing vulnerabilities in global supply chains while demonstrating both the capacity for rapid scientific response—mRNA vaccines developed in under a year—and the fragility of international cooperation when national interests conflict.\n\nArtificial intelligence emerged as potentially the most transformative technology since the industrial revolution. Large language models demonstrated human-level performance across an astonishing range of tasks, raising profound questions about the future of work, creativity, knowledge, and the relationship between humans and machines. Meanwhile, climate change continued to accelerate while geopolitical tensions over Taiwan, Ukraine, and other flashpoints reminded observers that great-power conflict remained a live possibility. The choices humanity makes in the coming decades about AI governance, climate action, and international cooperation will shape history as profoundly as any event covered in this course.' },
    ] },

  { id: 'ancient-05', eraId: 'ancient', order: 5, title: 'Ancient Egypt: Gods, Pharaohs, and the Afterlife', subtitle: 'Death, Divinity, and Eternal Power', estimatedMinutes: 15, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/a/af/All_Gizah_Pyramids.jpg',
    keyFacts: ['Pharaohs were considered living gods — incarnations of Horus', 'Mummification was practiced for over 2,000 years in Egypt', 'The Book of the Dead guided souls through the underworld', 'The Great Pyramid stood as the world\'s tallest structure for 3,800 years', 'Cleopatra VII was the last active pharaoh of Ancient Egypt'],
    relatedTimeline: ['t-pyramid', 't-egypt-afterlife', 't-ramesses'],
    sections: [
      { heading: 'The God-King: Power of the Pharaoh', body: 'In ancient Egypt, politics and religion were one. The pharaoh was not merely a king but a living god—the earthly incarnation of Horus, falcon deity of the sky—and upon death, merged with Osiris, ruler of the afterlife. This divine kingship was the cornerstone of Egyptian civilization for over 3,000 years.\n\nThe pharaoh\'s authority was total. As the intermediary between gods and humanity, he performed essential rituals that maintained Ma\'at—cosmic order, truth, and justice. Without Ma\'at, the Nile would not flood, crops would fail, and chaos would reign. This belief gave pharaohs unquestioned legitimacy and motivated subjects to dedicate lifetimes of labor to royal projects, including the construction of monuments designed to last forever.' },
      { heading: 'Mummification and the Journey to the Afterlife', body: 'The Egyptians were profoundly preoccupied with death—not out of morbidity, but from a passionate belief in eternal life. The process of mummification, refined over millennia, aimed to preserve the physical body so the soul (ka) could return to it. Embalmers removed organs, treated the body with natron salt for 40 days, wrapped it in linen, and surrounded it with protective amulets.\n\nThe deceased was then guided through the Duat—the underworld—by spells from the Book of the Dead. At the Hall of Two Truths, the god Anubis weighed the heart against the feather of Ma\'at. A heart heavy with sin was devoured by the monster Ammit; a heart light as a feather entered the paradise of the Field of Reeds. This elaborate theology drove investment in funerary art, tomb construction, and ritual texts—making Ancient Egypt one of history\'s most richly documented civilizations.' },
      { heading: 'The Pyramids: Engineering the Eternal', body: 'The Great Pyramid of Giza, built for Pharaoh Khufu around 2560 BCE, is composed of approximately 2.3 million stone blocks weighing 2.5–15 tonnes each. Constructed without iron tools, pulleys, or wheels, it stood as the world\'s tallest man-made structure for 3,800 years. The precision is staggering: the base is level to within 2.1 centimeters, and the four sides are aligned to the cardinal points of the compass with an error of less than 0.05 degrees.\n\nHow was this achieved? Thousands of skilled workers—not slaves, as was long assumed, but paid laborers who received bread, beer, medical care, and burial near the pharaoh—organized in rotating teams. Archaeology has revealed the workers\' villages, their bakeries and breweries, their graffiti boasting about their gangs. The pyramids were not built by broken people but by a civilization with extraordinary organizational capacity, motivated by genuine religious devotion.' },
      { heading: 'Egyptian Gods and the Cosmic Drama', body: 'The Egyptian pantheon featured hundreds of deities, often depicted with animal heads representing their divine qualities. Ra, the sun god, sailed his solar barque across the sky each day and through the underworld each night, battling the serpent Apophis. Osiris, murdered and dismembered by his jealous brother Set, was resurrected by his devoted wife Isis—a myth of death and renewal that resonated across millennia.\n\nIsis became one of the ancient world\'s most beloved goddesses, her cult eventually spreading throughout the Roman Empire. Thoth, the ibis-headed god of writing and knowledge, was credited with inventing hieroglyphics. Sekhmet, the lioness goddess of war, could both send plagues and cure them. These gods were not distant abstractions but active participants in daily life—protecting mothers in childbirth, guiding the deceased, and maintaining the celestial order that kept the Nile flooding on schedule.' },
      { heading: 'The New Kingdom and Egypt\'s Global Reach', body: 'Egypt\'s New Kingdom (c.1550–1070 BCE) was its most powerful era. Pharaohs like Thutmose III conquered an empire reaching from Nubia to Syria. Ramesses II (r.1279–1213 BCE), who ruled for 66 years and fathered over 100 children, signed history\'s earliest surviving peace treaty with the Hittites after the Battle of Kadesh.\n\nEgypt\'s final act belongs to Cleopatra VII (r.51–30 BCE), last of the Ptolemaic dynasty. A brilliant linguist who spoke nine languages, she formed strategic alliances with Julius Caesar and Mark Antony in a bid to preserve Egyptian independence against Rome. When Antony\'s forces were defeated at the Battle of Actium in 31 BCE, Cleopatra chose death over subjugation. With her, 3,000 years of pharaonic civilization came to an end—yet Egypt\'s art, religion, and mythology continued to fascinate and influence cultures across the world.' },
    ] },

  { id: 'medieval-04', eraId: 'middle-ages', order: 4, title: 'Medieval Economy: Trade Guilds and the Rise of Towns', subtitle: 'Commerce, Craft, and the Birth of the Bourgeoisie', estimatedMinutes: 14, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Medieval_manuscript_depicting_a_market_scene.jpg/1280px-Medieval_manuscript_depicting_a_market_scene.jpg',
    keyFacts: ['Medieval guilds controlled quality and training for skilled crafts', 'The Hanseatic League connected over 200 trading cities by the 14th century', 'The Black Death (1347–1351) killed 30–60% of Europe\'s population', 'Medieval fairs at Champagne attracted merchants from across Eurasia', 'The Medici banking family pioneered double-entry bookkeeping and bills of exchange'],
    relatedTimeline: ['t-black-death','t-mongol'],
    sections: [
      { heading: 'The Revival of Trade', body: 'The early medieval period (c.500–1000 CE) saw European trade contract dramatically after Rome\'s fall. Local lords became self-sufficient on their manors; long-distance commerce nearly vanished. But from around 1000 CE, conditions improved: the climate warmed slightly (the Medieval Warm Period), population grew, and agricultural surpluses created demand for goods beyond subsistence.\n\nMerchants began traveling regular circuits between growing towns. Weekly markets and annual fairs multiplied. The great Champagne Fairs in northeastern France became the commercial hub of Europe, attracting traders from Italy, Flanders, Germany, and the Levant. Here, silk and spices from the East changed hands for Flemish wool, Venetian glass, and German metalwork. A commercial revolution was underway.' },
      { heading: 'The Guilds: Masters of the Craft Economy', body: 'To regulate this commercial expansion, craftsmen and merchants formed guilds—associations that controlled entry into trades, set quality standards, and trained the next generation. Guilds encompassed everything from bakers and butchers to goldsmiths and surgeons. Becoming a master craftsman required years: first as an apprentice (living with the master\'s family), then as a journeyman (paid day laborer), and finally passing a masterpiece examination to join the guild as a full member.\n\nGuilds protected their members against outside competition, established apprenticeship ages, set wages, and enforced quality standards—inspectors could seize or destroy substandard goods. But they also served social functions: supporting sick members, sponsoring religious observances, organizing elaborate pageants and mystery plays. The guild system shaped urban economic life from the 12th century until the Industrial Revolution made it obsolete.' },
      { heading: 'The Hanseatic League: Medieval Globalization', body: 'In northern Europe, German merchant cities formed the Hanseatic League—a trading alliance that eventually encompassed over 200 towns from London to Novgorod, dominating Baltic and North Sea commerce for over two centuries. Lübeck served as the League\'s informal capital; Hamburg, Bremen, Danzig, and Riga were key members.\n\nHanseatic merchants developed sophisticated commercial practices: standardized weights and measures, commercial contracts, cargo insurance, and merchant courts to resolve disputes. Hanseatic trading posts (Kontore) in London, Bruges, Bergen, and Novgorod were virtual cities within cities, with their own warehouses, churches, and legal privileges. The Hansa\'s success demonstrated that medieval people were capable of extraordinary commercial sophistication—the roots of modern capitalism reached deep into the medieval town.' },
      { heading: 'The Black Death: Catastrophe and Transformation', body: 'The bubonic plague arrived in Europe from Central Asia in 1347, carried by fleas on rats aboard Genoese trading ships. Within four years, it killed between 30 and 60 percent of Europe\'s population—perhaps 25 million people. Entire villages vanished. The English village of Eyam would later seal itself off entirely during the 1665 plague to prevent its spread.\n\nThe demographic catastrophe transformed the economy. With labor suddenly scarce, surviving peasants could demand higher wages and better conditions—a major factor in the decline of serfdom. Landlords competed for workers; some peasants became freeholders for the first time. The plague also disrupted traditional authority, undermined faith in the Church\'s protective power, and may have accelerated the social changes that would culminate in the Renaissance and Reformation. Catastrophe, paradoxically, helped birth the modern world.' },
      { heading: 'Banking, Credit, and the Dawn of Capitalism', body: 'Medieval merchants required sophisticated financial tools. The Church condemned lending at interest as "usury," but clever bankers found workarounds. Italian merchants invented the bill of exchange—a written order allowing merchants to transfer credit across cities without physically moving gold, dramatically reducing the risk of robbery on medieval roads.\n\nThe Medici family of Florence rose to dominate 15th-century finance. Their banking network stretched across Europe, financing popes, kings, and merchants. Giovanni di Bicci de\' Medici and his descendants developed double-entry bookkeeping, branching structures to limit liability, and sophisticated credit instruments. Cosimo de\' Medici became the effective ruler of Florence—demonstrating that financial power could rival military power. The Medici patronage of art and scholarship made Florence the cradle of the Renaissance, linking commercial innovation directly to cultural revolution.' },
    ] },

  { id: 'earlymod-04', eraId: 'early-modern', order: 4, title: 'The Age of Absolutism: Louis XIV and Versailles', subtitle: 'The Sun King and the Zenith of Royal Power', estimatedMinutes: 14, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/Hall_of_Mirrors%2C_Versailles_%28by_Myrabella%29.jpg/1280px-Hall_of_Mirrors%2C_Versailles_%28by_Myrabella%29.jpg',
    keyFacts: ['Louis XIV ruled France for 72 years — the longest reign of any major monarch', 'The Palace of Versailles housed over 20,000 people at its peak', '"L\'état, c\'est moi" (I am the state) epitomizes absolute monarchy', 'Louis XIV revoked the Edict of Nantes in 1685, expelling French Protestants', 'The War of Spanish Succession (1701–1714) reshaped Europe\'s balance of power'],
    relatedTimeline: ['t-printing-press','t-reformation'],
    sections: [
      { heading: 'The Theory of Absolute Monarchy', body: 'Absolute monarchy reached its apotheosis in 17th-century France. The theory—articulated by Bishop Bossuet—held that kings derived their authority directly from God, owed accountability to no human institution, and possessed sovereignty over all within their realm. This "divine right of kings" justified rulers overriding parliaments, courts, and even the Church in their domains.\n\nPractical absolutism required more than theory: it demanded breaking the power of independent nobles, creating a centralized bureaucracy loyal to the crown, maintaining a professional army, and cultivating an ideology of royal magnificence that awed subjects into submission. No monarch pursued this agenda more systematically or brilliantly than Louis XIV of France.' },
      { heading: 'The Sun King: Louis XIV', body: 'Louis XIV (r.1643–1715) inherited the throne at age four after his father\'s death. During his minority, France was rocked by the Fronde—a series of aristocratic and popular revolts that nearly toppled the monarchy. Young Louis watched from hiding as Paris mobs invaded his bedroom; the experience hardened his determination never to be vulnerable to noble power again.\n\nTaking personal control of government in 1661, Louis declared himself the Sun King—the center around which all French life orbited. He abolished the role of prime minister, required nobles to live at his court rather than on their estates (neutralizing their independence), built an army of 400,000 men, and pursued an aggressive foreign policy aimed at making France the dominant power in Europe. "L\'état, c\'est moi"—"I am the state"—captured his vision perfectly.' },
      { heading: 'Versailles: The Palace as Political Instrument', body: 'The Palace of Versailles was Louis\'s greatest political achievement. Begun in 1661 and expanded over decades, it eventually housed the entire French court—some 20,000 people including nobles, servants, and courtiers. The palace\'s Hall of Mirrors, 73 meters long and lined with 357 mirrors reflecting the gardens beyond, was the most spectacular room in Europe.\n\nBut Versailles was not merely architectural vanity. It was a machine for political control. By requiring the most powerful nobles of France to live at Versailles and compete for royal favor—holding the king\'s candle, carrying his shirt—Louis transformed potential rebels into courtiers whose power came entirely from his approval. Away from their estates and distracted by elaborate court ritual, French nobles lost the independent power bases that might have threatened the monarchy. Every ceremony, every painting, every fountain was propaganda asserting Louis\'s divine grandeur.' },
      { heading: 'Religion, Revocation, and the Huguenots', body: 'Religious uniformity was integral to Louis\'s vision of absolute power. France had granted Protestant Huguenots religious freedoms under the 1598 Edict of Nantes, creating a state within a state that Louis found intolerable. In 1685, he revoked the Edict, declaring Protestantism illegal and forcing Huguenots to convert, flee, or face persecution.\n\nThe consequences were catastrophic for France and beneficial for its rivals. Approximately 200,000 Huguenots fled—many of them skilled craftsmen, merchants, and intellectuals. Prussia, England, and the Dutch Republic eagerly welcomed these refugees, gaining their skills and capital while France lost them. Frederick William of Brandenburg-Prussia offered resettlement to any Huguenot family, gaining silk weavers, watchmakers, and financiers who supercharged Prussian economic development. Louis\'s bigotry thus strengthened his enemies at France\'s expense.' },
      { heading: 'Absolutism\'s Limits and Legacy', body: 'Despite Louis\'s awesome power, absolute monarchy had significant limits. The king depended on the cooperation of provincial elites, the Church, and venal officeholders who had purchased their positions. Tax collection was inefficient; wars were ruinously expensive. By Louis\'s death in 1715, France was exhausted by decades of warfare—the War of Spanish Succession alone cost France vast resources and ended in the Treaty of Utrecht (1713), which blocked French hegemony in Europe.\n\nYet absolutism\'s legacy extended beyond France. Peter the Great of Russia consciously modeled himself on Louis XIV, importing French architects and courtiers to Westernize Russia. Frederick the Great of Prussia, Maria Theresa of Austria, and Catherine the Great of Russia all practiced "enlightened absolutism"—combining royal power with Enlightenment-era reforms. Absolutism also generated its own critique: Locke, Montesquieu, and Rousseau developed theories of limited government and popular sovereignty that would fuel the American and French Revolutions, ultimately destroying the absolute monarchies that absolutist theory had constructed.' },
    ] },

  { id: 'modern-05', eraId: 'modern', order: 5, title: 'The Age of Imperialism and the Scramble for Africa', subtitle: 'Empire, Exploitation, and Resistance', estimatedMinutes: 16, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Battle_of_Adwa_coloured.jpg/1280px-Battle_of_Adwa_coloured.jpg',
    keyFacts: ['By 1914, European powers controlled 84% of the world\'s land surface', 'The Berlin Conference of 1884–85 divided Africa without African input', 'Belgium\'s Congo Free State killed an estimated 10 million Congolese', 'The Zulu defeated the British at the Battle of Isandlwana in 1879', 'Ethiopia remained independent by defeating Italy at the Battle of Adwa in 1896'],
    relatedTimeline: ['t-ww1','t-russian-rev'],
    sections: [
      { heading: 'The Engines of Empire', body: 'The late 19th century saw European powers launch an unprecedented expansion across Africa, Asia, and the Pacific. Driven by industrial capitalism\'s need for raw materials and markets, nationalist competition between European states, and a racist ideology of "civilization," the imperial powers partitioned most of the world among themselves in a generation.\n\nTechnological superiority made conquest possible: steam-powered gunboats penetrated river systems; telegraph cables coordinated military operations across continents; the Maxim gun—the world\'s first modern machine gun—allowed small European forces to defeat vastly larger armies. Quinine finally made the African interior accessible to Europeans without mass death from malaria. As the poet Hilaire Belloc sardonic ally summarized: "Whatever happens, we have got / The Maxim gun, and they have not."' },
      { heading: 'The Scramble for Africa', body: 'Before 1880, European presence in Africa was largely confined to coastal trading posts. Then, in a breathtaking 30-year period, the entire continent—except Ethiopia and Liberia—was colonized. The Berlin Conference of 1884–85, convened by Otto von Bismarck, established the rules for this partition. Representatives of 14 European and American nations drew lines across the map of Africa, creating borders that ignored ethnic groups, kingdoms, trade networks, and physical geography.\n\nBritain gained the largest share: Egypt, Sudan, Nigeria, Ghana, Kenya, Uganda, Rhodesia (Zimbabwe), and South Africa. France dominated West and Central Africa. Belgium received the Congo; Germany got Namibia, Tanzania, and Cameroon; Italy took Libya and Somalia. Not a single African leader was consulted. These arbitrary borders became the independent nations of post-colonial Africa, creating ethnic tensions and conflicts that persist to the present day.' },
      { heading: 'The Horror of the Congo', body: 'No colony better illustrated imperialism\'s brutality than the Congo Free State, personally owned by Belgium\'s King Leopold II from 1885 to 1908. Leopold presented his rule as a humanitarian mission to bring "civilization" to Central Africa. In reality, he ran a terror state designed to extract maximum rubber and ivory profit.\n\nCongolese people were forced to harvest rubber under quotas; failure to meet targets was punished by mutilation—soldiers cut off the hands of workers and their family members to prove they had not wasted bullets. Millions died from violence, starvation, and disease. An international humanitarian campaign led by journalists E.D. Morel and humanitarian activist Roger Casement exposed the atrocities, creating one of the first international human rights campaigns in history. Under pressure, Leopold transferred the Congo to Belgian state control in 1908—but by then, an estimated 10 million people had died.' },
      { heading: 'Resistance: Africa Fights Back', body: 'Africans were not passive victims of conquest. Across the continent, kingdoms, confederations, and peoples mounted fierce resistance. The Zulu Kingdom of southern Africa, led by King Cetshwayo, inflicted the worst British military defeat in Africa at the Battle of Isandlwana in January 1879, killing over 1,300 British and allied troops in a single afternoon. Though the British ultimately prevailed, Zulu resistance forced a far more costly and careful campaign than expected.\n\nEthiopia\'s Emperor Menelik II achieved what no other African leader managed: he defeated a European colonial army outright. At the Battle of Adwa in March 1896, Ethiopian forces—numbering over 100,000 and equipped with modern weapons purchased from France and Russia—annihilated an Italian army of 17,000. Italy was forced to recognize Ethiopian independence in the subsequent Treaty of Addis Ababa. Adwa became a symbol of African resistance and pride, inspiring independence movements across the continent for generations.' },
      { heading: 'Imperial Legacy: The World We Inherited', body: 'By 1914, European empires controlled 84% of the world\'s land surface. The consequences were profound and lasting. Imperial extraction transferred vast wealth to Europe—British industrialization depended on Indian cotton, Caribbean sugar, and African minerals. Meanwhile, colonial economies were distorted to serve European needs rather than local development, creating structural dependencies that persisted long after independence.\n\nImperialism reshaped cultures, languages, and identities across the globe. Christian missionaries spread European education and religion while suppressing indigenous beliefs and languages. Colonial administrations created new ethnic hierarchies, often favoring one group over another to facilitate control—a divide-and-rule strategy with deadly long-term consequences. The wave of African and Asian independence that came after World War II (most African nations gained independence between 1956 and 1975) left nations grappling with arbitrary borders, economic underdevelopment, and cultural dislocation that are the direct legacy of the imperial age. Understanding imperialism is essential to understanding the modern world.' },
    ] },

  { id: 'modern-06', eraId: 'modern', order: 6, title: 'The Yugoslav Wars', subtitle: 'Nationalism, Genocide, and the Collapse of Yugoslavia', estimatedMinutes: 17, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/Grbavica_1996.jpg/1280px-Grbavica_1996.jpg',
    keyFacts: ['Yugoslavia dissolved violently between 1991 and 2001', 'The Bosnian War (1992–1995) included the Srebrenica massacre — Europe\'s worst genocide since WWII', 'NATO bombed Serbia in 1999 to stop the Kosovo War', 'The International Criminal Tribunal for the former Yugoslavia (ICTY) prosecuted war crimes', 'Slobodan Milošević was the first sitting head of state indicted for war crimes'],
    relatedTimeline: ['t-yugoslav-wars', 't-srebrenica'],
    sections: [
      { heading: 'The Socialist Federation and Its Fractures', body: 'Yugoslavia ("Land of the South Slavs") was created after World War I and reconstituted after World War II as a communist federation under Josip Broz Tito. Tito\'s charismatic leadership and the non-aligned foreign policy held together a mosaic of six republics — Slovenia, Croatia, Bosnia-Herzegovina, Serbia, Montenegro, and Macedonia — and two autonomous provinces, Kosovo and Vojvodina. These territories contained Serbs, Croats, Bosniaks (Bosnian Muslims), Slovenes, Macedonians, Albanians, Hungarians, and dozens of smaller groups, speaking different languages and practicing Orthodoxy, Catholicism, and Islam.\n\nTito suppressed nationalist movements ruthlessly and balanced power between republics. His famous phrase — "I have three countries: one past, one present, one future" — captured the fragile nature of Yugoslav unity. When Tito died in 1980, the system he built began to unravel. The rotating presidency created political vacuum; economic stagnation bred resentment; and nationalist politicians saw opportunity in inflaming ancient grievances that Tito had suppressed but never resolved.' },
      { heading: 'The Breakup Begins: Slovenia and Croatia', body: 'As communism collapsed across Eastern Europe in 1989–1991, Yugoslav republics moved toward independence. Serbia, under the nationalist Slobodan Milošević, sought to preserve Serbian dominance within a rump Yugoslavia. In June 1991, Slovenia and Croatia simultaneously declared independence. The Yugoslav People\'s Army (JNA) invaded Slovenia in the "Ten-Day War," but withdrew when it became clear Slovenia\'s geography — bordering Austria and Italy, with a tiny Serb minority — made control impractical.\n\nCroatia\'s case was far bloodier. Croatia had a significant Serbian minority (12%), and Serbian paramilitaries, backed by the JNA, seized control of the Krajina region and other Serbian-majority areas. Atrocities were committed by both sides. The city of Vukovar was shelled for 87 days and virtually destroyed before its surrender in November 1991 — a preview of the horrors to come in Bosnia. The international community, led by Germany, recognized Slovenian and Croatian independence in January 1992, a decision that accelerated the war\'s spread to Bosnia.' },
      { heading: 'Bosnia: Europe\'s Bloodiest War Since 1945', body: 'Bosnia-Herzegovina was the most ethnically mixed of Yugoslavia\'s republics: roughly 44% Bosniak (Muslim), 31% Serb, and 17% Croat in 1991. When Bosnia declared independence in March 1992, Bosnian Serbs — backed by Serbia and the JNA — immediately launched a war to carve out territory for a Serbian state (Republika Srpska). The Siege of Sarajevo, the longest siege of a capital city in the history of modern warfare, began in April 1992 and lasted 44 months. Sniper fire and artillery killed over 11,000 Sarajevo civilians.\n\nThe Bosnian Serb Army, under General Ratko Mladić, pursued a strategy of "ethnic cleansing" — expelling or massacring non-Serb populations to create ethnically pure territories. Concentration camps, systematic rape, and mass executions shocked the world. International peacekeepers (UNPROFOR) stood by largely helpless, their mandate limited by the UN Security Council\'s paralysis. The Srebrenica massacre of July 1995, in which over 8,000 Bosniak men and boys were murdered in a UN-declared "safe area," was the worst act of genocide in Europe since the Holocaust.' },
      { heading: 'Srebrenica: Never Again Happened Again', body: 'The fall of Srebrenica in July 1995 stands as the most catastrophic failure of international peacekeeping in the post-Cold War era. The town in eastern Bosnia had been declared a UN "safe area" in 1993 and was protected by a Dutch UN battalion (Dutchbat). When Mladić\'s forces encircled and entered Srebrenica on July 11, the Dutch peacekeepers — outnumbered and under-equipped — did not resist.\n\nBosniak men and boys ages 12–77 were separated from women and children and transported to mass execution sites over the following days. Bodies were buried in mass graves, then exhumed and reburied in secondary graves to conceal the evidence. The systematic nature of the killings — organized by military command, executed in coordinated fashion at multiple sites simultaneously — meets the legal definition of genocide under international law. The International Court of Justice confirmed this in 2007. Dutch peacekeepers watched as families were separated. The failure haunted the Netherlands, eventually leading to the resignation of the Dutch cabinet in 2002. Srebrenica became the emblem of humanity\'s failure to prevent genocide despite solemn post-Holocaust pledges.' },
      { heading: 'Kosovo, NATO Intervention, and the Aftermath', body: 'The wars temporarily paused with the Dayton Accords of November 1995, which ended the Bosnian War by partitioning Bosnia between the Bosniak-Croat Federation and Republika Srpska. But violence migrated to Kosovo — the Serbian province with a 90% Albanian majority. After peaceful resistance failed, the Kosovo Liberation Army (KLA) launched an insurgency in 1996. Milošević responded with brutal crackdowns that killed thousands of Albanian civilians and displaced hundreds of thousands.\n\nIn March 1999, NATO — without a UN Security Council mandate (Russia and China would have vetoed) — began an air campaign against Serbia lasting 78 days. Milošević withdrew from Kosovo; NATO deployed peacekeepers; and Kosovo eventually declared independence in 2008, recognized by over 100 countries though not by Serbia or Russia. Milošević was indicted by the ICTY in 1999 — the first sitting head of state charged with war crimes — and died in custody in 2006 before verdict. The Yugoslav Wars killed approximately 140,000 people, displaced over 2 million, and left a legacy of ethnic division, war crimes, and contested borders that still defines the Western Balkans.' },
    ] },

  { id: 'modern-07', eraId: 'modern', order: 7, title: 'The Macedonian Struggle', subtitle: 'A Nation\'s Fight for Identity in the Ottoman Decline', estimatedMinutes: 14, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Pavlos_Melas.jpg/800px-Pavlos_Melas.jpg',
    keyFacts: ['The Macedonian Struggle (1904–1908) was an armed conflict between Greek, Bulgarian, and Serbian forces for control of Ottoman Macedonia', 'The Internal Macedonian Revolutionary Organization (IMRO) launched the failed Ilinden Uprising in 1903', 'Greek-backed armed bands (andartes) battled Bulgarian comitadji in a guerrilla war', 'The Young Turk Revolution of 1908 temporarily ended the struggle', 'Macedonia was partitioned between Greece, Serbia, and Bulgaria after the Balkan Wars (1912–1913)'],
    relatedTimeline: ['t-macedonian-struggle', 't-balkan-wars'],
    sections: [
      { heading: 'Macedonia: The Prize Contested by All', body: 'At the turn of the 20th century, Macedonia was a geographical and historical region within the Ottoman Empire, covering roughly modern North Macedonia, northern Greece, and southwestern Bulgaria. It was one of the most ethnically complex territories in Europe: Orthodox Christians who could claim Greek, Bulgarian, or Serbian identity, Muslims (Turks and Slavic converts), Albanians, Jews, Vlachs, and Roma all lived in overlapping communities. With the Ottoman Empire clearly in terminal decline, Greece, Bulgaria, and Serbia each coveted Macedonia, and each claimed that its population was rightfully theirs.\n\nThe contest was not merely military but cultural and demographic. All three countries sent teachers, priests, and propagandists into Macedonia to win hearts and minds. Schools were opened; village populations were pressured to declare allegiance to the Greek Patriarchate or the Bulgarian Exarchate. The Bulgarian Exarchate (established 1870) was particularly effective, winning many Macedonian villagers away from the Greek Patriarchate — a demographic battle with profound political implications. A Macedonian who attended a Patriarchate school became "Greek" in census terms; one attending an Exarchate school became "Bulgarian."' },
      { heading: 'IMRO and the Ilinden Uprising', body: 'The Internal Macedonian Revolutionary Organization (IMRO), founded in Thessaloniki in 1893, sought an autonomous or independent Macedonia under the slogan "Macedonia for the Macedonians." IMRO was inspired by the precedent of Bulgaria\'s liberation and drew on a tradition of haiduk (bandit-rebel) resistance. Its networks extended through villages and diaspora communities; it collected taxes, executed collaborators, and organized guerrilla bands.\n\nOn August 2, 1903 — the Feast of Saint Elijah (Ilinden) — IMRO launched a major uprising across Macedonia and the adjacent Adrianople region. The Krushevo Republic, declared in the town of Krushevo, lasted ten days before Ottoman forces crushed it. The uprising failed militarily but became the founding myth of Macedonian national identity. The Ottomans\' brutal suppression — burning villages, massacring civilians, leaving 70,000 refugees — generated international sympathy and pressure for reform. The Mürzsteg Agreement between Austria-Hungary and Russia in October 1903 imposed a reform program on Macedonia, acknowledging the region\'s volatility and the empire\'s inability to manage it alone.' },
      { heading: 'The Guerrilla War: Greek vs. Bulgarian Bands', body: 'Following the Ilinden Uprising\'s failure, a new phase began: an organized guerrilla war between Greek and Bulgarian armed bands for control of the Macedonian population. Greece dispatched experienced officers and irregulars — the "andartes" — to work alongside Greek Patriarchate clergy in protecting Patriarchate villages and converting Exarchate ones back to Greek allegiance, often by force. Bulgaria\'s IMRO sent its own "comitadji" bands for the same purpose.\n\nThe struggle was characterized by extreme violence against civilians. Villages suspected of favoring the opposing side were burned; local leaders were assassinated; clergy were murdered. Macedonian peasants were caught between rival nationalisms, forced to choose allegiances — or to shift allegiances as military circumstances changed. Pavlos Melas, a Greek army officer who organized the Greek resistance in Macedonia before his death in 1904, became a national hero; dozens of Bulgarian and Greek fighters were similarly mythologized. This was a war fought not just for territory but for the very identity of a people who had never had a unified national consciousness.' },
      { heading: 'The Ottoman Context and the Young Turk Revolution', body: 'The Macedonian Struggle unfolded against the backdrop of Ottoman decline and reform. Sultan Abdul Hamid II\'s regime was under enormous pressure — from internal reformers, from European powers demanding protection of Christian minorities, and from nationalist movements across the Balkans. Macedonia was a tinderbox: the Mürzsteg reform program placed European officers in charge of reorganizing the Ottoman gendarmerie, an unprecedented intrusion into Ottoman sovereignty.\n\nThe Young Turk Revolution of July 1908 — launched by officers of the Committee of Union and Progress (CUP), many of them stationed in Macedonia itself — transformed the situation overnight. Abdul Hamid II was forced to restore the constitution and call elections. The revolution temporarily united all of Macedonia\'s communities in euphoric celebration: Muslims, Christians, and Jews embraced in the streets of Thessaloniki. The Greek and Bulgarian bands briefly stood down. But the constitutional honeymoon did not last; within months, intercommunal violence resumed, and the underlying national competition for Macedonia was merely suspended, not resolved.' },
      { heading: 'The Balkan Wars and Macedonia\'s Partition', body: 'The Macedonian question was finally resolved — partially and violently — by the Balkan Wars of 1912–1913. In the First Balkan War, Greece, Bulgaria, Serbia, and Montenegro formed the Balkan League and attacked the Ottoman Empire, which rapidly collapsed. Ottoman forces were pushed out of almost all their European territory within weeks; Macedonia fell to the League allies. In the Second Balkan War of June 1913, the allies fell out over the division of Macedonia: Bulgaria attacked Greece and Serbia simultaneously, but was defeated and forced to cede most of Macedonia to Greece and Serbia in the Treaty of Bucharest.\n\nGreece gained the largest share of Macedonia (Aegean Macedonia, including Thessaloniki). Serbia received Vardar Macedonia (roughly modern North Macedonia). Bulgaria retained only a small eastern strip (Pirin Macedonia). The partition satisfied no one completely. For Greece, Thessaloniki — a major city with a Jewish majority and mixed population — became the second city of the Greek state after a century of contest. For Bulgaria, the loss of most of Macedonia was a national trauma that drove Bulgarian foreign policy through both World Wars. The Macedonian Struggle thus ended not with Macedonian autonomy but with partition — a reminder that in the age of competing nationalisms, small peoples rarely controlled their own fate.' },
    ] },
  { id: 'ancient-06', eraId: 'ancient', order: 6, title: 'The Phoenicians: Masters of the Sea', subtitle: 'Alphabet, Trade, and the Purple Empire', estimatedMinutes: 13, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/PhoenicianShip.jpg/800px-PhoenicianShip.jpg',
    keyFacts: ['The Phoenicians invented the first alphabetic writing system around 1050 BCE', 'Carthage — founded by Tyre around 814 BCE — became the Mediterranean\'s greatest rival to Rome', 'Phoenician purple dye (from the murex sea-snail) was worth more than gold by weight', 'Phoenician sailors circumnavigated Africa for Pharaoh Necho II around 600 BCE', 'The word "alphabet" derives from the first two Phoenician letters: aleph and beth'],
    relatedTimeline: ['t-cuneiform','t-roman-republic'],
    sections: [
      { heading: 'The Purple People of the Levant', body: 'The Phoenicians occupied a narrow coastal strip of the eastern Mediterranean — roughly modern Lebanon — hemmed between the sea and the Lebanon Mountains. What they lacked in land they gained in maritime genius. Their great port cities — Tyre, Sidon, Byblos, Beirut — were among the ancient world\'s most prosperous commercial centers.\n\nThe Greeks called them "Phoinikes" — the Purple People — after Phoenicia\'s most celebrated product: a vivid crimson-purple dye extracted from the mucus of the murex sea-snail. Producing even a small amount required thousands of snails and reeked of decay during processing; the finished dye was rarer than gold. Only kings and high priests could afford Phoenician purple robes. The color "royal purple" retains its association with power and wealth to this day — a legacy of Phoenician commerce reaching across three thousand years.' },
      { heading: 'The Gift of the Alphabet', body: 'The Phoenicians\' most consequential contribution to civilization was neither purple dye nor merchant shipping, but writing. Around 1050 BCE, they developed a simplified alphabetic script of 22 consonants — a revolutionary simplification of the complex cuneiform and hieroglyphic systems that had required years of specialist training to master. A Phoenician merchant\'s apprentice could learn the system in weeks.\n\nThis practicality made it irresistible. The Greeks adopted the Phoenician alphabet around the 9th century BCE, adding vowels to create the ancestor of every Western alphabet. Greek became Latin; Latin became Italian, French, Spanish, English, and dozens of other languages. The Aramaic version spread east, becoming the parent of Hebrew, Arabic, and the scripts of South Asia. Every time you read or write, you are using a system descended from Phoenician merchants who needed an efficient way to record cargo manifests and commercial transactions. No single cultural invention has had wider impact on human history.' },
      { heading: 'Merchants of the Mediterranean', body: 'Phoenician trading ships ventured wherever there was profit to be made. They pioneered routes westward through the Mediterranean, around Sicily and Sardinia, through the Strait of Gibraltar — which they called the "Pillars of Melqart" — and along the Atlantic coasts of Europe and Africa. Their merchant vessels, sturdy round-hulled "hippos" (named for their horse-head prows), could carry cargo of 30–50 tonnes, navigating by stars and accumulated knowledge passed from captain to captain.\n\nThe Phoenicians established trading posts and colonies across the Mediterranean: on Cyprus, Sardinia, Malta, Sicily, the Balearic Islands, and coastal Spain. They traded Canaanite wine and oil, Egyptian linen, Mesopotamian textiles, Cypriot copper, Spanish silver, and African ivory. Their commercial networks were more extensive than any previous civilization\'s, creating the template for Mediterranean trade that Greeks, Carthaginians, and Romans would later inherit and expand.' },
      { heading: 'Carthage: The Daughter City That Outgrew Its Mother', body: 'Around 814 BCE, according to tradition, Queen Dido of Tyre led a group of exiles to establish Carthage ("New City") on a promontory on the North African coast near modern Tunis. Whether or not the legendary founding is accurate, Carthage rapidly outgrew all Phoenician mother cities. Its triple harbors — one for commerce, one for the navy, one for the royal fleet — could simultaneously accommodate 220 warships.\n\nBy the 4th century BCE, Carthage controlled the western Mediterranean\'s trade, ruling a commercial empire that encompassed North Africa, Spain, Sardinia, and Sicily. Its citizen army of mercenaries — Numidian cavalry, Spanish infantry, Greek officers — was the most formidable western Mediterranean force. Carthage\'s clash with the rising Roman Republic in the three Punic Wars (264–146 BCE) would prove civilization-altering. Rome eventually prevailed — razing Carthage to the ground in 146 BCE — but only after Hannibal\'s genius had brought Rome to the brink of destruction. The struggle between Rome and Carthage shaped the entire future of Western civilization.' },
      { heading: 'The Legacy of a Seafaring People', body: 'The Phoenicians vanished as a distinct people, absorbed into the expanding Hellenistic and later Roman worlds, but their legacy proved indestructible. The alphabet, modified by every civilization that encountered it, became the tool through which human knowledge was recorded and transmitted across millennia. Without Phoenician writing, there would be no Homer, no Bible, no classical philosophy, no scientific literature.\n\nPhoenician seamanship charted the world: Greek geographers later reported that Phoenician sailors, commissioned by Egypt\'s Pharaoh Necho II around 600 BCE, circumnavigated the entire continent of Africa — a feat not repeated by Europeans until Vasco da Gama in 1488 CE. Their discovery that the sun appeared to their north during the southern part of the voyage was considered unbelievable by Herodotus — yet it was precisely this detail that convinced modern scholars the account was genuine. In their restless, commercial, seafaring spirit, the Phoenicians prefigured something distinctly modern: the idea that the world exists to be explored, traded with, and connected.' },
    ] },


  { id: 'medieval-05', eraId: 'middle-ages', order: 5, title: 'The Mongol Empire', subtitle: 'Genghis Khan and the Pax Mongolica', estimatedMinutes: 16, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4a/YuanEmperorAlbumGenghisPortrait.jpg/800px-YuanEmperorAlbumGenghisPortrait.jpg',
    keyFacts: ['Genghis Khan united the Mongol tribes in 1206 CE', 'The Mongol Empire became the largest contiguous land empire in history', 'The Pax Mongolica facilitated trade from China to Europe', 'The Mongols destroyed Baghdad in 1258, ending the Abbasid Caliphate', 'Kublai Khan founded the Yuan Dynasty in China in 1271'],
    relatedTimeline: ['t-mongol','t-silk-road'],
    sections: [
      { heading: 'The Rise of Genghis Khan', body: 'In the harsh steppes of Central Asia, a boy named Temüjin was born around 1162 CE into a minor Mongol clan. After years of hardship—his father poisoned by rivals, Temüjin himself held captive—he rose through a combination of extraordinary military talent, political cunning, and ruthless determination to unite the perpetually feuding Mongol tribes.\n\nIn 1206, at a grand assembly (kurultai) of Mongol chiefs beside the Onon River, Temüjin was proclaimed Genghis Khan—"Universal Ruler." He immediately transformed the assembled tribes into a disciplined military machine organized on decimal principles: units of ten, hundred, thousand, and ten thousand. Loyalty was to the unit and the Khan, not to the clan—a revolutionary change that ended the tribal warfare that had weakened the Mongols for generations.' },
      { heading: 'The Strategy of Conquest', body: 'Mongol armies were the most effective military force of the medieval world, combining mobility, discipline, psychological warfare, and tactical sophistication. Mounted archers could cover 80–100 km per day, operating across vast distances that would have immobilized infantry armies. Before a battle, Mongol envoys offered cities a stark choice: surrender and be spared, or resist and face total destruction.\n\nCities that submitted were generally treated with pragmatic leniency—their artisans, engineers, and administrators were absorbed into the Mongol state machine. Cities that resisted were razed as warnings to others. When the great city of Zhongdu (modern Beijing) fell in 1215, foreign travelers reported that the bones of its residents whitened the plains for miles. This combination of mercy and terror proved devastatingly effective: news of Mongol campaigns often caused cities to submit without a fight.' },
      { heading: 'The Empire at Its Peak', body: 'By Genghis Khan\'s death in 1227, the Mongols controlled an empire stretching from the Pacific coast of China to the Caspian Sea. His successors pushed even further. Ögedei Khan completed the conquest of northern China; Batu Khan swept through Russia and Poland, reaching the Adriatic before withdrawing. Hülegü Khan sacked Baghdad in 1258, killing the Abbasid Caliph and ending five centuries of Islamic cultural supremacy.\n\nAt its height, the Mongol Empire was the largest contiguous land empire in history, covering 24 million square kilometers—roughly the size of Africa. It encompassed the majority of the Eurasian landmass and held perhaps 100 million people under its rule. No empire before or since has achieved such rapid territorial expansion across such diverse geographical and climatic zones.' },
      { heading: 'The Pax Mongolica: Trade and Cultural Exchange', body: 'Paradoxically, the most destructive conquest in history created one of its most productive periods of cultural exchange. The Pax Mongolica ("Mongol Peace"), roughly 1260–1350, unified the trade routes of Eurasia under a single political umbrella for the first time. Merchants, diplomats, missionaries, and travelers could journey from China to Europe with relative safety, carrying goods, ideas, technologies, and diseases along the Silk Road.\n\nMarco Polo\'s famous journey to the court of Kublai Khan (1271–1295) was only possible because of Mongol order. Chinese papermaking, gunpowder, and printing technologies traveled westward; Islamic astronomy and medicine moved eastward. The Mongol courts actively recruited skilled people regardless of religion or origin—Christian priests, Muslim astronomers, Chinese engineers, and Persian bureaucrats all served at the Yuan court in Beijing. This cosmopolitan exchange accelerated the technological and commercial development that would eventually fuel the European Renaissance and Age of Exploration.' },
      { heading: 'Legacy: Destruction and Creation', body: 'The Mongol conquests killed an estimated 40 million people—perhaps 10% of the world\'s population—and permanently altered the demographic landscape of Central Asia and the Middle East. Iran\'s population may not have recovered to pre-Mongol levels for 700 years. The destruction of Baghdad\'s irrigation systems contributed to the long-term agricultural decline of Mesopotamia. The once-great cities of Central Asia—Samarkand, Bukhara, Merv—never fully recovered their pre-Mongol vitality.\n\nYet Mongol rule also created. Kublai Khan\'s Yuan Dynasty (1271–1368) brought dramatic economic development to China: paper money was standardized, the Grand Canal extended, and the postal relay system (yam) enabled communication across the empire with unprecedented speed. The Mongol successor states—the Il-Khanate in Persia, the Golden Horde in Russia, the Chagatai Khanate in Central Asia—gradually converted to Islam and adopted local cultures, producing distinctive artistic and architectural traditions. Russia\'s long Mongol subjugation shaped its autocratic political culture. The Mongol moment, brief as it was, permanently reordered Eurasia.' },
    ] },

  { id: 'medieval-06', eraId: 'middle-ages', order: 6, title: 'Medieval Japan: Samurai, Shoguns and Bushidō', subtitle: 'Warriors, Honor, and the Way of the Sword', estimatedMinutes: 15, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/48/Oda_Nobunaga.jpg/800px-Oda_Nobunaga.jpg',
    keyFacts: ['The samurai class emerged in the 10th century as provincial warriors', 'The Genpei War (1180–1185) established the first shogunate under Minamoto no Yoritomo', 'Zen Buddhism deeply influenced samurai culture and aesthetics', 'Mongol invasions of Japan in 1274 and 1281 were repelled partly by typhoons called "kamikaze"', 'The Sengoku ("Warring States") period lasted from 1467 to 1615'],
    relatedTimeline: ['t-mongol','t-silk-road'],
    sections: [
      { heading: 'The Birth of the Samurai', body: 'Japan\'s imperial court at Heian-kyō (modern Kyoto) reached its cultural zenith in the 10th–11th centuries, producing extraordinary literature and art. But governing the distant provinces required warriors—mounted archers hired from aristocratic families. These provincial warriors, called samurai ("those who serve"), gradually evolved from imperial retainers into a distinct military class with its own values and aesthetics.\n\nSamurai society was organized around the lord-vassal relationship: a samurai pledged absolute loyalty to his lord (daimyō) in exchange for land and protection. The warrior ethos that developed—later codified as Bushidō, "the Way of the Warrior"—emphasized loyalty (chū), honor (meiyo), martial skill, and the acceptance of death. A samurai who lost his honor or whose lord died was expected to commit ritual suicide (seppuku) rather than live in disgrace. This austere code shaped Japanese culture for centuries.' },
      { heading: 'The Genpei War and the Rise of the Shogunate', body: 'The rivalry between Japan\'s two most powerful warrior clans—the Taira (Heike) and the Minamoto (Genji)—erupted into the Genpei War (1180–1185), a conflict that became one of the defining narratives of Japanese culture. The Minamoto, led by the brilliant general Minamoto no Yoshitsune, defeated the Taira in a series of battles culminating in the naval Battle of Dan-no-ura, where the child emperor Antoku drowned with the Taira fleet.\n\nMinamoto no Yoritomo, Yoshitsune\'s elder brother, established Japan\'s first shogunate (military government) at Kamakura in 1185—a parallel government that effectively superseded the imperial court. The emperor retained ceremonial authority; real power lay with the shogun. This dual structure of nominal imperial rule and actual military governance persisted, with variations, until 1868. The Genpei War\'s stories—Yoshitsune\'s genius and tragic fate, the Taira\'s destruction—were immortalized in the Tale of the Heike, Japan\'s great warrior epic.' },
      { heading: 'Zen Buddhism and the Samurai Aesthetic', body: 'Zen Buddhism, introduced from China in the late 12th century, found its most receptive audience among the samurai class. Zen\'s emphasis on direct experience over scripture, its meditation practices that cultivated mental clarity under pressure, and its acceptance of impermanence resonated deeply with warriors who faced death as a daily reality. Zen masters became spiritual advisors to shoguns and daimyō alike.\n\nZen aesthetics profoundly shaped Japanese culture. The tea ceremony (chanoyu), garden design, ink painting (suiboku-ga), Noh theater, and flower arrangement (ikebana) all reflect the Zen values of simplicity, impermanence, and disciplined attention. Even sword-making became a spiritual art: a master swordsmith purified himself ritually before forging a blade, and the finished katana was considered a soul in steel. This fusion of martial pragmatism and refined aesthetic sensibility produced one of the world\'s most distinctive cultural traditions.' },
      { heading: 'The Mongol Invasions and Japanese Identity', body: 'In 1274 and 1281, the Yuan Empire of Kublai Khan launched two massive invasion attempts against Japan—the largest amphibious operations in medieval history. The first fleet of 900 ships and 40,000 warriors arrived in Hakata Bay in November 1274, fighting off Japanese samurai with superior crossbows, explosive bombs, and coordinated infantry tactics that individual Japanese warriors were not trained to counter. But a sudden storm damaged the fleet, and the Mongols withdrew.\n\nThe second invasion in 1281 was far larger: 4,400 ships and up to 140,000 troops. After weeks of fighting on the beaches and aboard anchored ships, a massive typhoon—the famous "divine wind" or kamikaze—destroyed most of the fleet. Japan was saved. But the victory had devastating consequences: the samurai defenders expected land grants as reward, but there was no conquered territory to distribute. The resulting economic strain weakened the Kamakura shogunate and contributed to its eventual collapse in 1333. The kamikaze mythology became a cornerstone of Japanese national identity, invoked again—with tragic results—during the Second World War.' },
      { heading: 'The Sengoku Period and Unification', body: 'The Ōnin War of 1467–1477, fought over the shogunal succession in the streets of Kyoto, shattered what remained of central authority and plunged Japan into the Sengoku ("Warring States") period—a century and a half of near-constant warfare between competing daimyō. Castles were built across the landscape; peasants were conscripted as infantry (ashigaru); the introduction of firearms by Portuguese traders in 1543 transformed tactics.\n\nUnification came through three successive "great unifiers." Oda Nobunaga—ruthless, innovative, and brilliant—used firearms and shock tactics to defeat rivals before his assassination in 1582. His general Toyotomi Hideyoshi, a peasant\'s son risen to supreme power, completed unification and launched two catastrophic invasions of Korea. After Hideyoshi\'s death, Tokugawa Ieyasu defeated his rivals at the Battle of Sekigahara (1600) and established the Tokugawa Shogunate—a stable government that would rule Japan in deliberate isolation from the rest of the world for the next 260 years, preserving samurai culture in amber until the modern era forced open Japan\'s doors.' },
    ] },

  { id: 'medieval-07', eraId: 'middle-ages', order: 7, title: 'The Viking Age', subtitle: 'Raiders, Traders, and Settlers of the North', estimatedMinutes: 15, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Oseberg_ship_head_post.jpg/800px-Oseberg_ship_head_post.jpg',
    keyFacts: ['The Viking Age is dated from the raid on Lindisfarne (793) to the Battle of Stamford Bridge (1066)', 'The clinker-built longship, with its shallow draft, let Norsemen raid up rivers and cross open ocean alike', 'Swedish Varangians founded Kievan Rus and traded as far as Baghdad and Constantinople', 'Norse settlers reached Iceland (c.874), Greenland (c.985), and North America (c.1000)', 'In 911 the Frankish king granted Normandy to the Viking leader Rollo — ancestor of the Normans'],
    relatedTimeline: ['t-charlemagne','t-hastings'],
    sections: [
      { heading: 'The Storm from the North', body: 'On 8 June 793, seaborne raiders fell upon the monastery of Lindisfarne off the coast of Northumbria, slaughtering monks and carrying off its treasures. The scholar Alcuin, writing from Charlemagne\'s court, was aghast: "Never before has such terror appeared in Britain as we have now suffered from a pagan race." The raid announced the Viking Age — nearly three centuries in which Norse seafarers from Denmark, Norway, and Sweden would reshape the map of Europe.\n\nWhat drove them is still debated. Population pressure on limited Scandinavian farmland, political consolidation that pushed out ambitious younger sons, the lure of the undefended wealth of monasteries, and above all a revolution in shipbuilding all played a part. The Norse were not a unified people or empire but a scatter of chieftains, traders, and war-bands who shared a language, a pantheon of gods, and a genius for the sea. To their victims they were heathen monsters; to themselves they were farmers, poets, and merchants for whom a season of raiding was one enterprise among many.' },
      { heading: 'The Longship: Engineering the Age', body: 'No single technology defined the Viking Age more than the longship. Clinker-built from overlapping oak planks, light and flexible, it drew as little as a metre of water yet could ride the open Atlantic. A single square sail drove it at speed before the wind; banks of oars powered it in a calm or up a river. Its symmetrical hull could reverse direction without turning, and it could be beached on any shore or carried overland between waterways.\n\nThis meant no coast, no river town, no island was safe. A Viking fleet could appear without warning, strike, and be gone before a defence could gather. The same ships that terrorised Paris and Seville carried colonists and their livestock across a thousand miles of open ocean to Iceland. The longship was warship, cargo vessel, and ocean explorer in one — and around it the Norse built a maritime culture unmatched in medieval Europe. The great ship-burials at Oseberg and Gokstad in Norway preserve these vessels almost intact, their carved prows still curving toward the horizon.' },
      { heading: 'Raiders Become Rulers', body: 'Raiding gave way to conquest and settlement. In England, a "Great Heathen Army" landed in 865 and overran the kingdoms of Northumbria, East Anglia, and Mercia; only Alfred the Great\'s Wessex held out, and even Alfred had to concede the north and east to Danish law — the Danelaw, whose place-names ending in "-by" and "-thorpe" still mark the English map. The Norse founded or grew towns like Jorvik (York) and Dublin into thriving centres of trade in silver, slaves, and craft.\n\nIn Francia, repeated raids up the Seine culminated in the siege of Paris (885–886). Rather than keep fighting, the Frankish king Charles the Simple bought peace in 911 by granting the Viking leader Rollo the land at the mouth of the Seine — Normandy, "the land of the Northmen." Within a few generations Rollo\'s descendants had become French-speaking Christian dukes; one of them, William, would conquer England in 1066. The Vikings did not merely plunder Europe — they settled into it, and their descendants became some of its most powerful rulers.' },
      { heading: 'The Eastern Rivers and the Road to Byzantium', body: 'While Danes and Norwegians looked west, Swedish Vikings — the Rus — turned east, dragging their boats between the great rivers of the Eurasian plain. Following the Volga and the Dnieper "from the Varangians to the Greeks," they traded furs, amber, and slaves for the silver of the Islamic caliphates; hoards of Arabic coins found across Scandinavia trace these journeys. Around these river routes they built a state, ruling from Novgorod and then Kiev — the Kievan Rus, ancestor of Russia and Ukraine.\n\nThe Rus reached the walls of Constantinople itself, sometimes as raiders, more often as traders and mercenaries. The Byzantine emperors prized them so highly that they formed the elite Varangian Guard from Norse and later Anglo-Saxon warriors. In 988 the Rus prince Vladimir accepted Orthodox Christianity from Byzantium, binding the eastern Slavs to Constantinople rather than Rome — a decision whose religious and cultural consequences still echo across eastern Europe a thousand years later.' },
      { heading: 'The Edge of the World, and the End of an Age', body: 'The Norse pushed the boundaries of the known world further than any Europeans before them. They settled Iceland from around 874, creating a remarkable commonwealth governed by the Althing, one of the world\'s oldest assemblies. From Iceland, Erik the Red led settlers to Greenland around 985. And from Greenland his son Leif Erikson sailed further still, reaching a land he called Vinland — confirmed by the Norse site at L\'Anse aux Meadows in Newfoundland, proof that Europeans reached the Americas five centuries before Columbus.\n\nThe age that began at Lindisfarne ended, by convention, at Stamford Bridge in 1066, where the English king Harold Godwinson destroyed the invading army of Harald Hardrada of Norway — the last great Viking conqueror. Weeks later Harold himself fell to William of Normandy, a Viking\'s descendant, at Hastings. By then the Scandinavian kingdoms had become Christian and settled, their energies turned inward. But the Viking legacy endured: in the towns they founded, the states they seeded, the sagas they told, and the enduring image of the dragon-prowed longship cutting through northern seas.' },
    ] },

  { id: 'earlymod-05', eraId: 'early-modern', order: 5, title: 'The Transatlantic Slave Trade', subtitle: 'Captivity, Commerce, and the Making of the Atlantic World', estimatedMinutes: 16, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Slaveshipposter.jpg/800px-Slaveshipposter.jpg',
    keyFacts: ['An estimated 12.5 million Africans were transported across the Atlantic between 1500 and 1900', 'The Middle Passage killed roughly 15–20% of all enslaved people during the crossing', 'The sugar economy of the Caribbean depended entirely on enslaved African labor', 'Olaudah Equiano\'s autobiography (1789) helped build the British abolitionist movement', 'Britain abolished the slave trade in 1807, slavery itself in 1833'],
    relatedTimeline: ['t-columbus','t-american-revolution'],
    sections: [
      { heading: 'Origins: Sugar, Profit, and the Demand for Labor', body: 'The transatlantic slave trade emerged from the intersection of European colonialism, the sugar revolution, and the catastrophic collapse of Indigenous American populations. Sugar—"white gold"—grew only in tropical climates and required immense quantities of brutal labor for planting, harvesting, and processing. The Portuguese pioneered sugar cultivation in Brazil using enslaved Africans from the 1530s; the system spread to the Caribbean as Dutch, English, and French colonies expanded through the 17th century.\n\nBy the mid-17th century, the Caribbean sugar islands—Barbados, Jamaica, Saint-Domingue (Haiti), Cuba—had become fabulously profitable. A single Jamaican sugar plantation generated returns of 10% or more annually. This profitability created insatiable demand for labor. Indigenous people had been largely destroyed by European diseases; European indentured servants were expensive and temporary. Enslaved Africans, procured from West African kingdoms that had centuries of experience in slave trading, became the answer.' },
      { heading: 'The Slave Trade in Operation', body: 'The transatlantic slave trade operated through a brutal triangular system. European ships departed with manufactured goods—textiles, guns, iron bars, alcohol—to West African ports. There, they traded with African kings, merchants, and raiders who supplied enslaved people captured in wars and raids in the African interior. The enslaved were then transported across the Atlantic—the Middle Passage—and sold to planters in the Americas. The ships returned to Europe laden with sugar, tobacco, cotton, and rum.\n\nBetween approximately 1500 and 1900, an estimated 12.5 million Africans were forcibly embarked on slave ships, mostly from West and Central African coasts—the Bight of Benin, the Congo River basin, Senegambia, and Angola. Of these, roughly 10.7 million survived the crossing. At its peak in the 18th century, 80,000 enslaved Africans crossed the Atlantic every year. The trade involved every major European maritime power—Portugal, Spain, Britain, France, the Netherlands, and Denmark—and the profits funded banking, manufacturing, and colonial infrastructure across Europe.' },
      { heading: 'The Middle Passage: Horror at Sea', body: 'The Middle Passage—the sea voyage from Africa to the Americas—was one of history\'s most sustained atrocities. Enslaved people were packed into ships\' holds with horrifying density, chained in pairs, lying in spaces sometimes only 45 cm high. The voyage lasted three to eight weeks depending on weather and destination. Mortality from dysentery, smallpox, scurvy, and dehydration ran between 15% and 20%—meaning that one in six enslaved people died during the crossing.\n\nResistance was continuous. Revolts aboard slave ships were common despite the extreme disadvantages faced by the enslaved—chains, unfamiliar languages among different African groups, and armed crews. The most successful slave ship revolt occurred aboard the Amistad in 1839, when enslaved Africans led by Sengbe Pieh seized the vessel and eventually secured their freedom through American courts. The lived experience of the Middle Passage—the bodies thrown overboard, the children separated from parents, the deliberate dehumanization—was documented by survivors and formed the moral foundation of the abolitionist movement.' },
      { heading: 'Slavery in the Americas: Life and Resistance', body: 'In the plantation colonies of the Americas, enslaved people labored under conditions of extraordinary brutality. On sugar plantations—the most lethal environment—annual death rates could reach 5–10%, meaning the enslaved population required constant replenishment from Africa. Enslaved people worked 18-hour days during harvest season, operating the machinery of the sugar mill around the clock. Punishments for resistance, slow work, or perceived insolence were savage and public, designed to terrorize.\n\nYet enslaved people were never passive victims. They maintained African cultural and religious traditions—music, dance, language, spirituality—that created community and sustained resistance. Maroon communities of escaped enslaved people established independent societies in the mountains of Jamaica, the forests of Suriname, and the Brazilian interior. Slave revolts punctuated the entire history of New World slavery; the Haitian Revolution (1791–1804) was the only successful large-scale slave rebellion in history, producing the first Black republic and permanently transforming debates about slavery and freedom worldwide.' },
      { heading: 'Abolition and Legacy', body: 'The abolitionist movement emerged in the late 18th century from a convergence of Enlightenment thought, Quaker religious principles, and the testimonies of formerly enslaved people like Olaudah Equiano, whose published autobiography (1789) brought the reality of slavery to British readers with devastating effect. The movement mobilized grassroots campaigns—petitions signed by hundreds of thousands, sugar boycotts, pamphlets—that built sustained political pressure over decades.\n\nBritain abolished the slave trade in 1807 and slavery itself in 1833—compensating slaveholders £20 million (financed by a loan not repaid until 2015) while providing nothing to the formerly enslaved. The United States abolished slavery only after the Civil War in 1865. The transatlantic slave trade\'s legacy persists in structural racial inequalities across the Americas, the demographic transformation of the Caribbean and Brazil, and the cultural richness—music, language, religion—that African survivors and their descendants created under conditions of extreme oppression. Understanding this history is essential to understanding the contemporary world.' },
    ] },

  { id: 'earlymod-06', eraId: 'early-modern', order: 6, title: 'The Ottoman Empire: Suleiman the Magnificent', subtitle: 'Islam, Law, and the Zenith of Ottoman Power', estimatedMinutes: 15, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/ea/Suleiman_the_Magnificent2.jpg/800px-Suleiman_the_Magnificent2.jpg',
    keyFacts: ['The Ottoman Empire at its height controlled three continents and 15–25 million people', 'Suleiman I ruled for 46 years (1520–1566), the longest reign of any Ottoman sultan', 'The Siege of Vienna in 1529 marked the westernmost extent of Ottoman expansion', 'Ottoman law (kanun) was codified by Suleiman, earning him the title "the Lawgiver"', 'The Battle of Lepanto (1571) was the first major Ottoman naval defeat'],
    relatedTimeline: ['t-printing-press','t-reformation'],
    sections: [
      { heading: 'The Rise of the Ottoman State', body: 'The Ottoman Empire was founded around 1299 by the Turkish chieftain Osman I in northwestern Anatolia, one of dozens of small Turkish principalities that emerged after the Mongol destruction of the Seljuk Sultanate. What distinguished the Ottomans was their position on the Byzantine frontier—a geography that produced a warrior culture oriented toward continuous expansion and attracted Muslim holy warriors (ghazi) from across the Islamic world.\n\nOttoman expansion proceeded with remarkable speed. By 1389, Ottoman forces had defeated the Serbian kingdom at the Battle of Kosovo, bringing the Balkans under their control. In 1453, Sultan Mehmed II ("the Conqueror") achieved what no Muslim ruler had accomplished in eight centuries: he captured Constantinople, the ancient Roman capital and seat of Eastern Christianity, using massive bronze cannons to breach its legendary walls. The fall of Constantinople shocked Christian Europe and gave the Ottomans undisputed control of the straits connecting the Mediterranean and Black Seas—the single most strategic location in the known world.' },
      { heading: 'Suleiman the Magnificent: The Lawgiver', body: 'Suleiman I, who came to power in 1520 at age twenty-six, presided over the zenith of Ottoman civilization. Europeans called him "the Magnificent" for his splendor and military power; his own subjects called him "Kanuni"—the Lawgiver—for his most lasting achievement: a comprehensive codification of Ottoman law (kanun) that harmonized Islamic sharia with Ottoman administrative custom and practice.\n\nSuleiman\'s law code regulated taxation, land tenure, criminal justice, and the conduct of officials. It was remarkably progressive for its era—protecting peasants from arbitrary expropriation, setting limits on punishments, and establishing due-process guarantees. His grand vizier Ibrahim Pasha managed day-to-day administration with extraordinary effectiveness; the imperial council (Divan) operated with a sophistication that European monarchs envied. Suleiman\'s court at Topkapı Palace, where 30,000 people lived and worked, was the most magnificent in the world—a center of architecture, poetry, calligraphy, and scientific learning.' },
      { heading: 'Military Campaigns and the Limits of Empire', body: 'Suleiman\'s military campaigns reshaped the map of the world. In 1521, he captured Belgrade—gateway to Central Europe. In 1522, he expelled the Knights of St. John from Rhodes after a six-month siege. At the Battle of Mohács in 1526, Ottoman forces annihilated the Hungarian army and killed the young king Louis II, bringing most of Hungary under Ottoman control. The Siege of Vienna in 1529 marked the westernmost advance of Ottoman power into Europe, halted less by Habsburg resistance than by overextended supply lines and the onset of winter.\n\nAt sea, the Ottoman admiral Hayreddin Barbarossa defeated the combined Christian fleet at Preveza in 1538, establishing Ottoman dominance of the Mediterranean. The Ottomans extended their reach to the Indian Ocean, challenging Portuguese control of the spice trade. By Suleiman\'s death in 1566—he died on campaign in Hungary—the empire stretched from Algeria to Azerbaijan, from Hungary to Yemen. Managing this vast territory required a sophisticated administrative apparatus: governors (pashas), a meritocratic military-administrative class (the devshirme system, recruiting talented boys from conquered Christian populations), and the world\'s most effective bureaucracy.' },
      { heading: 'Ottoman Society: A Multi-Faith Empire', body: 'The Ottoman Empire governed an extraordinarily diverse population through the millet system: non-Muslim communities (Orthodox Christians, Armenian Christians, Jews) were organized as semi-autonomous communities under their own religious leaders, who were responsible to the Ottoman state for their communities\' behavior and tax payments. Within their millets, these communities maintained their own courts, schools, and religious institutions.\n\nThis system was no utopia—non-Muslims paid the jizya (poll tax) and faced various legal disadvantages. But compared to the religious persecutions of Reformation Europe—where Protestant and Catholic communities tortured and burned each other—Ottoman tolerance was real and significant. When the Spanish Inquisition expelled the Jews in 1492, Sultan Bayezid II actively recruited them to Ottoman cities, famously mocking Ferdinand of Aragon for "impoverishing his kingdom while enriching mine." Jewish, Armenian, and Greek communities thrived as merchants, physicians, and scholars in Istanbul, Thessaloniki, and other Ottoman cities.' },
      { heading: 'Ottoman Culture and Legacy', body: 'The Ottoman Empire produced magnificent cultural achievements. The architect Mimar Sinan (1489–1588), a Greek Christian conscripted through the devshirme, designed over 300 buildings for Suleiman and his successors—among them the Süleymaniye Mosque in Istanbul and the Selimiye Mosque in Edirne, considered the pinnacle of Ottoman architecture. Ottoman poetry, calligraphy, miniature painting, and ceramic arts (İznik tiles) reached heights of refinement that shaped Islamic art across the world.\n\nThe Ottoman Empire survived Suleiman by over three centuries, finally dissolving after World War I in 1922. At its collapse, it was replaced by a rump Turkish state under Mustafa Kemal Atatürk, who abolished the caliphate and systematically Westernized Turkish institutions. The Ottoman legacy shapes the modern Middle East profoundly: the empire\'s arbitrary dissolution by European powers after WWI—carving up Arab territories in the Sykes-Picot Agreement—created the boundaries of Iraq, Syria, Lebanon, and Palestine, establishing conflicts that remain unresolved to this day. Understanding the Ottomans is essential to understanding the contemporary Middle East.' },
    ] },

  { id: 'earlymod-07', eraId: 'early-modern', order: 7, title: 'The Age of Revolution', subtitle: 'America, France, and the Birth of Modern Democracy', estimatedMinutes: 17, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a7/Declaration_of_Independence_%281819%29%2C_by_John_Trumbull.jpg/1280px-Declaration_of_Independence_%281819%29%2C_by_John_Trumbull.jpg',
    keyFacts: ['The American Declaration of Independence was signed on 4 July 1776', 'The French Revolution began in 1789 with the storming of the Bastille', 'The Declaration of the Rights of Man and Citizen (1789) proclaimed universal liberty and equality', 'The Reign of Terror (1793–94) executed over 17,000 people, including Marie Antoinette', 'Napoleon Bonaparte rose to power in 1799, spreading revolutionary ideals across Europe'],
    relatedTimeline: ['t-american-revolution','t-french-revolution'],
    sections: [
      { heading: 'The American Revolution: Enlightenment Into Action', body: 'By the 1760s, Britain\'s thirteen American colonies had developed a distinctive political culture rooted in Enlightenment ideas about natural rights, representative government, and the social contract. When Britain imposed new taxes after the Seven Years\' War—the Stamp Act (1765), the Townshend Acts (1767)—without granting the colonists representation in Parliament, the slogan "no taxation without representation" crystallized a constitutional grievance into a revolutionary program.\n\nThe Boston Tea Party of December 1773, in which colonists dumped 342 chests of tea into Boston Harbor to protest the Tea Act, provoked harsh British reprisals. Open conflict began at Lexington and Concord in April 1775. The Second Continental Congress appointed George Washington to command the Continental Army. On 4 July 1776, the Congress adopted Thomas Jefferson\'s Declaration of Independence—the most consequential political document of the modern era. Steeped in John Locke\'s philosophy, it proclaimed that "all men are created equal" and possess "unalienable rights" to "life, liberty, and the pursuit of happiness," and that government derives its just powers from the consent of the governed.' },
      { heading: 'Winning Independence', body: 'The War of Independence (1775–1783) was by no means inevitable. The Continental Army faced a professional British military and suffered devastating early defeats. Washington\'s crucial victory at Trenton on 26 December 1776—a surprise crossing of the icy Delaware River on Christmas night—restored morale and kept the revolution alive.\n\nThe turning point came at the Battle of Saratoga in October 1777, where American forces captured an entire British army. This triumph convinced France to formally ally with the Americans, providing ships, soldiers, and loans without which American victory would have been impossible. The final decisive engagement came at Yorktown in October 1781, where Washington and the French commander Rochambeau trapped Cornwallis\'s army between land forces and the French fleet. Cornwallis surrendered, and the Treaty of Paris (1783) recognized American independence.' },
      { heading: 'The French Revolution: Liberté, Égalité, Fraternité', body: 'France in the 1780s was in crisis: a bankrupt state, harvest failures causing bread prices to soar, and an aristocracy unwilling to pay taxes. When Louis XVI called the Estates-General in May 1789—the first meeting in 175 years—the Third Estate (commoners) broke away and declared themselves a National Assembly, claiming the right to remake France\'s constitution.\n\nOn 14 July 1789, a Paris crowd stormed the Bastille fortress, a symbol of royal tyranny—the moment that marks the revolution\'s beginning. The National Assembly abolished feudalism overnight on 4 August, then issued the Declaration of the Rights of Man and Citizen, proclaiming liberty, equality before the law, freedom of speech, and national sovereignty. These principles became the revolution\'s ideological core. Louis XVI was forced to accept a constitutional monarchy; the old regime was dead. France was reorganized into departments, the Church was nationalized, and hereditary privilege abolished.' },
      { heading: 'The Reign of Terror and Its Aftermath', body: 'The revolution quickly grew more radical and more violent. War with Austria and Prussia from 1792, combined with internal counter-revolutionary rebellions, created a siege mentality in Paris. The radical Jacobin faction, led by Maximilien Robespierre, seized control of the Committee of Public Safety in 1793 and launched the Reign of Terror: a systematic execution of "enemies of the revolution" that sent over 17,000 people to the guillotine, including Louis XVI (January 1793) and Marie Antoinette (October 1793).\n\nThe Terror consumed itself: in July 1794, Robespierre\'s own colleagues turned on him ("Thermidorian Reaction"), and he was guillotined the next day. A more conservative Directory ruled from 1795 until 1799, but proved too weak to manage France\'s wars and internal conflicts. Into this vacuum stepped a brilliant young Corsican artillery officer: Napoleon Bonaparte.' },
      { heading: 'Napoleon and the Revolutionary Legacy', body: 'Napoleon Bonaparte\'s coup of 18 Brumaire (November 1799) ended the Revolution and began the Consulate, then the Empire (1804). Napoleon presented himself as the consolidator of revolutionary gains: his Civil Code (1804) enshrined equality before the law, property rights, and religious toleration—while also restricting women\'s rights and reimposing social hierarchy. His conquests spread the Code and revolutionary institutions across Europe, dissolving feudal structures from Spain to Poland.\n\nYet Napoleon\'s imperial ambitions ultimately provoked a coalition of European powers that defeated him at Leipzig (1813) and Waterloo (1815), ending with his exile to St Helena. The Vienna Congress tried to restore the old order, but the revolutionary genie could not be returned to the bottle. The ideas of popular sovereignty, natural rights, and national self-determination spread across the 19th century, fueling revolutions from Latin America to Greece to 1848 Europe. The American and French Revolutions together established the foundational vocabulary of modern democracy — freedom, equality, and the right to self-governance — that shapes political life to this day.' },
    ] },

  { id: 'ancient-07', eraId: 'ancient', order: 7, title: 'Ancient Macedonia: Alexander the Great', subtitle: 'From Pella to the Edge of the World', estimatedMinutes: 16, xpReward: 110, imageUrl: 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Alexandermosaic.jpg/1280px-Alexandermosaic.jpg',
    keyFacts: ['Philip II rebuilt the Macedonian army around the 6-metre sarissa pike and the Companion cavalry', 'Alexander became king at 20 and never lost a battle in eleven years of campaigning', 'The Battle of Gaugamela (331 BCE) destroyed the Persian Empire — the largest empire the world had yet known', 'Alexander founded over twenty cities named Alexandria; the Egyptian one became the ancient world\'s greatest centre of learning', 'His death at 32 in Babylon (323 BCE) split the empire among his generals and opened the Hellenistic Age'],
    relatedTimeline: ['t-alexander','t-persian-wars','t-cyrus-great'],
    sections: [
      { heading: 'The Kingdom on the Edge of the Greek World', body: 'North of Mount Olympus, beyond the city-states that considered themselves the centre of civilisation, lay Macedonia — a rough kingdom of highland shepherds, lowland farmers, and hard-riding aristocrats. Southern Greeks dismissed the Macedonians as half-barbarians who drank their wine unmixed and settled politics with hunting spears. Yet the kingdom possessed what the fractured city-states did not: timber, gold mines, wide cavalry plains, and a single royal house — the Argeads — who claimed descent from Herakles.\n\nFrom the capital at Pella, and the old royal seat of Aigai where the kings were buried, Macedonia watched the Greek world exhaust itself in endless wars between Athens, Sparta, and Thebes. In 359 BCE a twenty-three-year-old prince named Philip inherited a battered kingdom on the edge of collapse — and within two decades turned it into the most formidable military power on earth.' },
      { heading: 'Philip II: The Architect of Empire', body: 'Philip II understood that battles are won by organisation, not heroics. He armed his infantry with the sarissa — a pike up to six metres long — and drilled them into a phalanx that presented an impenetrable hedge of iron points. He paired this anvil with a hammer: the Companion cavalry, the finest shock horsemen of the age. He perfected siegecraft, professionalised pay, and married strategically across the Balkans.\n\nOne by one, Philip absorbed the gold mines of Thrace, the ports of Chalkidiki, and Thessaly\'s cavalry country. When Athens and Thebes finally combined against him at Chaeronea in 338 BCE, his army shattered them in a single afternoon — his eighteen-year-old son Alexander leading the decisive cavalry charge. Philip forced the Greek states into the League of Corinth under his leadership and prepared a grand invasion of Persia. In 336 BCE, at his daughter\'s wedding in Aigai, he was assassinated by his own bodyguard — and the throne, the army, and the Persian project passed to Alexander.' },
      { heading: 'The Conquest of Persia', body: 'Alexander crossed into Asia in 334 BCE with roughly 40,000 men, throwing a spear into the shore to claim the continent as "spear-won" land. At the river Granicus he broke the first Persian army sent against him. At Issus (333 BCE) he routed King Darius III himself, capturing the royal family. Refusing Darius\'s offer of half the empire — "I would accept," said his general Parmenion, "if I were Alexander"; "So would I," Alexander replied, "if I were Parmenion" — he turned south instead.\n\nTyre, the impregnable island fortress, fell after a seven-month siege in which Alexander built a causeway across the sea. Egypt welcomed him as a liberator and crowned him pharaoh; on the Nile delta he traced the streets of Alexandria, the greatest of the twenty cities that would bear his name. Then, at Gaugamela in 331 BCE, outnumbered perhaps five to one, he annihilated Darius\'s last great army. Babylon, Susa, and Persepolis — with its treasury of 120,000 talents — fell in succession. The empire of Cyrus was his.' },
      { heading: 'To the Ends of the Earth', body: 'Most conquerors would have stopped. Alexander marched on — through the Hindu Kush, across Bactria and Sogdiana, hunting Darius\'s murderers and crushing revolt after revolt in three years of brutal mountain warfare. He married the Bactrian noblewoman Roxana, adopted Persian court dress, and began treating conquered peoples as subjects to be governed rather than enemies to be looted — policies his Macedonian veterans increasingly resented.\n\nIn 326 BCE he descended into the Punjab and defeated King Porus and his war elephants at the river Hydaspes, in perhaps his most tactically brilliant battle. He pressed east toward the Ganges — but at the river Hyphasis his exhausted army, eight years and 20,000 kilometres from home, refused to take another step. For the only time in his life, Alexander was defeated — by his own men. The retreat through the Gedrosian desert killed more of his soldiers than all his battles combined.' },
      { heading: 'Death in Babylon and the Hellenistic Legacy', body: 'Back in Babylon, planning an Arabian expedition, Alexander fell into a sudden fever after a night of heavy drinking. On 11 June 323 BCE he died in Nebuchadnezzar\'s palace, one month short of thirty-three. Asked on his deathbed to whom he left the empire, he reportedly whispered "to the strongest." His generals — the Diadochi — obliged, tearing the empire apart in forty years of war: Ptolemy took Egypt, Seleucus took Asia, Antigonus\'s heirs took Macedonia itself.\n\nYet the conquest outlived the conqueror. Greek became the common tongue from the Adriatic to Afghanistan; Greek cities, theatres, and gymnasia sprouted across three continents; Alexandria\'s Library and Museum made Egypt the intellectual capital of the world. This Hellenistic civilisation — Greek culture fused with Persian, Egyptian, and Indian traditions — shaped the world Rome would inherit, the world the New Testament would be written in. The boy from Pella had not merely conquered the ancient world; he had rewired it.' },
    ] },
];

export function getLessonById(id: string) { return LESSONS.find(l => l.id === id); }
export function getEraLessons(eraId: string) { return LESSONS.filter(l => l.eraId === eraId).sort((a,b) => a.order - b.order); }
